'use strict';

// 清和觀・知止籤／99 首原創心籤。保留原版 1–24，新增 25–99。皆為虛構作品，非現存宮觀籤譜。
const TRANSLATION_DATA = {"title":"清和觀｜知止籤・九九籤三語資料","version":"translation-draft-1.0","languages":["zh-Hant","ja","en"],"gradeLabels":{"zh-Hant":{"上吉":"上吉","吉":"吉","中吉":"中吉","平":"平","待時":"待時"},"ja":{"上吉":"上吉","吉":"吉","中吉":"中吉","平":"平","待時":"時を待つ"},"en":{"上吉":"Very Favorable","吉":"Favorable","中吉":"Moderately Favorable","平":"Neutral","待時":"Wait for the Right Time"}},"categoryLabels":{"ja":{"感情":"恋愛","婚姻":"結婚","人際":"人間関係","家宅":"家庭・住まい","事業":"仕事","財務":"金銭・財務","學業／進修":"学業・学び","健康／身心":"健康・心身","抉擇":"選択","運勢轉折":"転機","隨緣／綜合":"人生・総合"},"en":{"感情":"Love","婚姻":"Marriage","人際":"Relationships","家宅":"Home & Family","事業":"Career","財務":"Finances","學業／進修":"Study & Learning","健康／身心":"Health & Well-being","抉擇":"Decisions","運勢轉折":"Turning Points","隨緣／綜合":"General Guidance"}},"lots":[{"id":1,"zh-Hant":{"id":1,"name":"初晴","grade":"上吉","poem":["簷雨才收盡","階前有微光","莫嫌行路緩","腳下自生香"],"meaning":"一段反覆不明的情況，正慢慢露出輪廓。你未必需要立刻追上別人的進度，先把眼前能做的事做好，變化便有落腳處。","action":"挑一件拖了許久、卻只需十分鐘就能開始的事，今天動手。","quote":"「天晴不保證路乾，但至少看得清腳下。」"},"ja":{"name":"初晴（はつばれ）","originalName":"初晴","grade":"上吉","poem":["軒先の雨は上がり","石段に淡い光","歩みの遅さを嘆くな","足もとから香り立つ"],"meaning":"何度も輪郭の見えなかった状況が、少しずつ形を現し始めています。すぐに誰かの進度へ追いつく必要はありません。まず目の前にできることを整えれば、変化にも足場が生まれます。","action":"長く先延ばしにしていたことのうち、十分あれば始められるものを一つ選び、今日手をつけましょう。","quote":"「晴れたからといって道が乾いたとは限らぬ。だが、足もとは見えるようになった。」"},"en":{"name":"First Clear Skies","originalName":"初晴","grade":"Very Favorable","poem":["The eaves have shed their rain;","A faint light rests on the steps.","Do not begrudge your measured pace;","Even the ground beneath you blooms."],"meaning":"A situation that has remained unclear is gradually coming into focus. You do not have to catch up with someone else’s pace at once. Take care of what is within reach, and the change will find somewhere to take root.","action":"Choose one thing you have put off that would take only ten minutes to begin, and start it today.","quote":"“Clear skies do not guarantee a dry road. At least now you can see where you are stepping.”"}},{"id":2,"zh-Hant":{"id":2,"name":"留白","grade":"中吉","poem":["紙上未題字","窗前風已來","若將空處滿","何地放花開"],"meaning":"空白不是失敗，也不是什麼都沒有。事情尚未定形時，留一些餘地，能讓新的可能進來。","action":"把原本排滿的行程留一小段空檔，不急著安排用途。","quote":"「話說滿了，茶倒滿了，都不太好端。」"},"ja":{"name":"余白","originalName":"留白","grade":"中吉","poem":["紙にはまだ字がなく","窓辺には風が来る","空いたところを埋めたら","花の咲く場所はどこに"],"meaning":"空白は失敗でも、何もないということでもありません。物事がまだ形を持たないとき、少し余地を残せば、新しい可能性が入り込めます。","action":"予定を詰め込まず、使い道を決めない空き時間を少し残しておきましょう。","quote":"「言葉を詰め込みすぎても、茶を注ぎすぎても、うまく運べぬものだ。」"},"en":{"name":"The Blank Space","originalName":"留白","grade":"Moderately Favorable","poem":["No words have touched the page;","A breeze has reached the window.","Fill every empty space,","And where will the flowers bloom?"],"meaning":"An empty space is neither failure nor nothingness. When things have yet to take shape, leaving room allows new possibilities to enter.","action":"Leave a small opening in your schedule without deciding in advance how to use it.","quote":"“A cup filled to the brim is hard to carry. The same goes for a conversation.”"}},{"id":3,"zh-Hant":{"id":3,"name":"歸舟","grade":"吉","poem":["遠岸浮燈影","歸舟識舊汀","潮平風未定","且向岸邊行"],"meaning":"你正在找一個可以安穩靠近的方向。比起遠處模糊的承諾，當下能不能安心、能不能互相照應，更值得留心。","action":"聯繫一位讓你相處時不用勉強自己的人。","quote":"「回得去的地方，不一定要很大。」"},"ja":{"name":"帰り舟","originalName":"歸舟","grade":"吉","poem":["遠い岸に灯が浮かび","帰り舟は古い洲を知る","潮は静まり風はまだ定まらず","まず岸辺へ向かおう"],"meaning":"あなたは安心して近づける場所を探しています。遠くにある曖昧な約束より、今ここで安心できるか、互いに支え合えるかに目を向けてください。","action":"一緒にいるとき、無理に自分を取り繕わずにいられる人へ連絡してみましょう。","quote":"「帰ってこられる場所は、必ずしも広くなくてよい。」"},"en":{"name":"The Returning Boat","originalName":"歸舟","grade":"Favorable","poem":["Lights drift along the distant shore;","The returning boat knows its old inlet.","The tide is calm, but the wind unsettled;","For now, make for the shore."],"meaning":"You are looking for a direction you can approach with a sense of safety. More than distant, uncertain promises, notice whether you feel at ease here and whether care can be mutual.","action":"Reach out to someone with whom you do not have to pretend to be someone else.","quote":"“A place you can return to does not have to be large.”"}},{"id":4,"zh-Hant":{"id":4,"name":"定水","grade":"平","poem":["杯中波未息","照影總難真","放下搖杯手","方知水與人"],"meaning":"眼前的紛亂也許不全來自外界。當你一直試著確認答案，反而看不清本來的樣子。先停下反覆測試的動作。","action":"把「我已知道的事實」和「我正在猜的事」各寫兩句。","quote":"「水沒停，你一直照鏡子，能怪鏡子晃嗎？」"},"ja":{"name":"静水","originalName":"定水","grade":"平","poem":["杯の水はまだ揺れ","映る姿も定まらない","杯を揺らす手を離して","水と人の姿を知る"],"meaning":"目の前の混乱は、すべて外から来ているとは限りません。答えを確かめようと何度も試すほど、本来の姿が見えなくなることもあります。いったん確認を繰り返す手を止めましょう。","action":"「すでに分かっている事実」と「今、自分が推測していること」を、それぞれ二つ書き出しましょう。","quote":"「水が止まらぬうちから鏡をのぞき続けて、揺れる鏡を責めるのかね。」"},"en":{"name":"Still Water","originalName":"定水","grade":"Neutral","poem":["The water in the cup still trembles;","The reflection cannot yet be true.","Release the hand that shakes the cup,","And see both water and self."],"meaning":"Not all the turmoil before you necessarily comes from outside. The more you repeatedly test for an answer, the harder it may become to see what is there. Pause the cycle of checking.","action":"Write down two things you know as facts and two things you are currently guessing.","quote":"“If the water has not settled and you keep looking into it, can you blame the mirror for wavering?”"}},{"id":5,"zh-Hant":{"id":5,"name":"候風","grade":"待時","poem":["竹影斜過牆","新枝未及長","不爭一夜綠","且守寸根香"],"meaning":"此刻適合準備，不必硬推進度。等候不是把選擇交出去，而是知道什麼時候用力，才不會把自己耗光。","action":"確認手上已具備的資源，找出還缺的最小一項。","quote":"「等風可以，別連鞋都不穿。」"},"ja":{"name":"風を待つ","originalName":"候風","grade":"時を待つ","poem":["竹の影が塀を渡り","新しい枝はまだ伸びない","一夜で青くなろうとせず","ひと節の根を守ろう"],"meaning":"今は準備に向いた時期です。進み具合を無理に押し上げる必要はありません。待つことは選択を手放すことではなく、自分をすり減らさずに力を使う時を知ることです。","action":"手元にある資源を確認し、まだ足りない最小のものを一つ見つけましょう。","quote":"「風を待つのはよい。だが、靴まで脱いで待つことはない。」"},"en":{"name":"Waiting for the Wind","originalName":"候風","grade":"Wait for the Right Time","poem":["Bamboo shadows cross the wall;","The new shoot has yet to grow.","Do not demand a green world overnight;","Guard the life within one small root."],"meaning":"This is a time for preparation, not for forcing progress. Waiting does not mean surrendering your choices; it means knowing when to apply your strength without wearing yourself down.","action":"Review the resources you already have and identify the smallest thing still missing.","quote":"“It is fine to wait for the wind. Just do not take off your shoes while you wait.”"}},{"id":6,"zh-Hant":{"id":6,"name":"開門","grade":"吉","poem":["門前無落鎖","客至有新聲","一盞茶先暖","何須問遠程"],"meaning":"某個機會可能來自很平常的交談或邀請。不用立刻決定全部，只要願意看見新的入口。","action":"回覆一則被你擱置、但其實願意回應的訊息。","quote":"「開門是讓人進來談，不是把房契送他。」"},"ja":{"name":"開かれた門","originalName":"開門","grade":"吉","poem":["門には錠がかかっておらず","客の訪れに新しい声","まず一杯の茶を温めよう","遠い先まで問わずともよい"],"meaning":"機会は、ごく普通の会話や誘いから訪れるかもしれません。すべてをすぐに決める必要はなく、新しい入口に気づくことから始めれば十分です。","action":"返事をしたいと思いながら後回しにしていたメッセージに、一つ返信しましょう。","quote":"「門を開けるのは話をするためであって、家の権利書を渡すためではない。」"},"en":{"name":"The Open Gate","originalName":"開門","grade":"Favorable","poem":["The gate is not locked;","A visitor brings a new voice.","First, warm a cup of tea;","There is no need to ask how far it leads."],"meaning":"An opportunity may arrive through an ordinary conversation or invitation. You do not have to decide everything immediately; being willing to notice a new opening is enough.","action":"Reply to one message you have postponed even though you would like to respond.","quote":"“Opening the gate means letting someone in to talk, not handing over the deed to your house.”"}},{"id":7,"zh-Hant":{"id":7,"name":"種竹","grade":"中吉","poem":["泥裡初埋節","春深始見青","人間多近利","竹自向風聽"],"meaning":"真正有價值的進展，往往在看不見的地方先發生。現在不需要向誰證明結果，把基本功做好就足夠。","action":"為長期目標做一件小而可重複的事。","quote":"「根還沒長好，別急著拿竹子搭棚。」"},"ja":{"name":"竹を植える","originalName":"種竹","grade":"中吉","poem":["泥の中に節を埋め","春深くして初めて青くなる","世は目先の利を追うけれど","竹はただ風の声を聴く"],"meaning":"本当に価値のある進歩は、目に見えない場所から始まることがよくあります。今は誰かに成果を証明しなくてよいのです。基礎を整えるだけで十分です。","action":"長期的な目標のために、小さくても繰り返せることを一つ行いましょう。","quote":"「根が育つ前から、竹で棚を組もうと急がぬことだ。」"},"en":{"name":"Planting Bamboo","originalName":"種竹","grade":"Moderately Favorable","poem":["A node is buried in the soil;","Only deep in spring does green appear.","The world chases its immediate gain;","Bamboo simply listens to the wind."],"meaning":"Progress of real value often begins where no one can see it. You do not need to prove your results to anyone right now. Building the foundations is enough.","action":"Do one small, repeatable thing in service of a long-term goal.","quote":"“Do not rush to build a shelter out of bamboo before its roots have grown.”"}},{"id":8,"zh-Hant":{"id":8,"name":"相照","grade":"吉","poem":["雙燈隔小窗","光影各成雙","不必爭高下","同明一夜長"],"meaning":"兩個人可以有不同的節奏與想法，仍能相互照亮。好的關係不靠猜測彼此心意，而靠有來有往的確認。","action":"用一句直接的話表達需求，不要求對方猜。","quote":"「你有你的燈，我有我的，不用搶一個開關。」"},"ja":{"name":"照らし合う","originalName":"相照","grade":"吉","poem":["小窓を隔てて二つの灯","光と影はそれぞれに重なる","高低を競う必要はない","ともに夜を照らせばよい"],"meaning":"二人は異なるペースや考えを持ちながら、互いを照らすことができます。よい関係は相手の心を当てることではなく、言葉と応答を交わして確かめることで育ちます。","action":"相手に察してもらおうとせず、必要としていることを一言で直接伝えましょう。","quote":"「あなたにはあなたの灯、私には私の灯がある。スイッチを奪い合わなくてよい。」"},"en":{"name":"Mutual Light","originalName":"相照","grade":"Favorable","poem":["Two lamps glow beyond a little window;","Each casts its own light and shade.","There is no need to compete for height;","Together, they can light the night."],"meaning":"Two people can have different rhythms and ideas while still illuminating one another. A good relationship is not built on guessing what the other feels, but on asking, answering, and confirming.","action":"State one thing you need directly, without expecting the other person to guess.","quote":"“You have your lamp, and I have mine. We do not need to fight over one switch.”"}},{"id":9,"zh-Hant":{"id":9,"name":"遠路","grade":"中吉","poem":["山外仍有山","橋頭又一灣","回看來時處","已過數重關"],"meaning":"你可能太在意還有多少路，忘了自己已經走過哪些難處。方向可以調整，先承認眼下的累積，才有力氣走下一段。","action":"記下最近一個月自己處理好的三件事。","quote":"「你說還沒到，我知道；但也不是站在原地。」"},"ja":{"name":"遠き道","originalName":"遠路","grade":"中吉","poem":["山の向こうにも山があり","橋の先にはまた湾曲がある","来た道を振り返れば","幾つもの難所を越えている"],"meaning":"まだどれほど道が残っているかに気を取られ、すでに越えてきた困難を忘れているのかもしれません。進路は変えてもかまいません。まず今まで積み重ねたものを認めることが、次へ進む力になります。","action":"この一か月で、自分がうまく対処できたことを三つ書き留めましょう。","quote":"「まだ着いていないのは分かる。だが、ずっと同じ場所にいたわけでもあるまい。」"},"en":{"name":"The Long Road","originalName":"遠路","grade":"Moderately Favorable","poem":["Beyond one mountain, another rises;","Past the bridge, the road bends again.","Look back at the way you came:","You have crossed more than one hard pass."],"meaning":"You may be so focused on how far you still have to go that you forget the difficulties you have already crossed. Your direction can change. First acknowledge what you have built; that will give you strength for the next stretch.","action":"Write down three things you handled well over the past month.","quote":"“I know you have not arrived yet. But you have not been standing still, either.”"}},{"id":10,"zh-Hant":{"id":10,"name":"故紙","grade":"平","poem":["舊頁藏微塵","翻開字尚新","當年未解意","今日另看真"],"meaning":"舊經驗值得參考，卻未必能直接回答現在的問題。若同一件事總讓你受困，也許該重新檢查當時的理解。","action":"替一件舊事寫出至少一種不同於原先的解釋。","quote":"「以前看錯字，不代表這本書得燒掉。」"},"ja":{"name":"古い頁","originalName":"故紙","grade":"平","poem":["古い頁に細かな塵","開けば文字はまだ新しい","あの頃には読めなかった意味も","今日なら違って見える"],"meaning":"過去の経験は参考になりますが、今の問題にそのまま答えてくれるとは限りません。同じことに何度もつまずくなら、当時の受け止め方を見直す時かもしれません。","action":"過去の出来事を一つ選び、当時とは異なる解釈を少なくとも一つ書いてみましょう。","quote":"「昔、字を読み違えたからといって、この本を燃やす必要はない。」"},"en":{"name":"Old Pages","originalName":"故紙","grade":"Neutral","poem":["Dust rests upon an old page;","Its words still look new when opened.","What once escaped your understanding","May reveal another truth today."],"meaning":"Past experience is worth consulting, but it may not directly answer the question you face now. If the same issue keeps troubling you, it may be time to reconsider how you understood it before.","action":"Choose one past event and write at least one interpretation different from the one you held at the time.","quote":"“Misreading a word once does not mean the whole book must be burned.”"}},{"id":11,"zh-Hant":{"id":11,"name":"轉角","grade":"吉","poem":["巷深人未見","轉角忽聞香","若問前方路","且循一線光"],"meaning":"不必等到全貌清楚才開始行動。當下的小線索，可能比遠大的想像更可靠；但仍要記得邊走邊核對。","action":"選一條低風險的路先試一步，觀察實際回饋。","quote":"「找不到出口，至少先把門把試一遍。」"},"ja":{"name":"曲がり角","originalName":"轉角","grade":"吉","poem":["路地の奥に人影はなく","角を曲がれば香りが漂う","前方の道を問うなら","まず一筋の光をたどろう"],"meaning":"全体像がはっきりするまで行動を待つ必要はありません。今ある小さな手がかりは、大きな想像より頼りになることがあります。ただし、進みながら確かめることを忘れずに。","action":"リスクの低い道を一つ選んで小さく試し、実際の反応を観察しましょう。","quote":"「出口が見つからぬなら、せめて先にドアノブを試してみなさい。」"},"en":{"name":"Around the Corner","originalName":"轉角","grade":"Favorable","poem":["No one appears at the end of the lane;","A fragrance drifts around the corner.","If you ask what lies ahead,","Follow the narrow thread of light."],"meaning":"You do not need to wait for the whole picture to become clear before acting. A small clue at hand may be more reliable than a grand imagined future. Just remember to keep checking as you go.","action":"Choose one low-risk path, take a small step, and observe the actual response.","quote":"“If you cannot find the exit, at least try the doorknob first.”"}},{"id":12,"zh-Hant":{"id":12,"name":"燈下","grade":"中吉","poem":["燈下人相對","無言亦可親","若將心事說","茶暖到更深"],"meaning":"有些關係不必靠熱鬧維繫。真正需要時，一句具體而誠懇的話，會比漫長的試探更有用。","action":"向值得信任的人說出一個明確而不誇張的感受。","quote":"「貧道會泡茶，但不能替你把話講完。」"},"ja":{"name":"灯の下","originalName":"燈下","grade":"中吉","poem":["灯の下で人は向かい合い","言葉がなくとも親しみはある","胸の内を語れば","茶の温もりは夜更けまで続く"],"meaning":"にぎやかさで保つ必要のない関係もあります。本当に必要なときには、具体的で誠実な一言が、長い探り合いより役に立ちます。","action":"信頼できる人に、誇張せず、はっきりと自分の気持ちを一つ伝えましょう。","quote":"「茶は淹れてやれるが、話すところまでは代わってやれぬ。」"},"en":{"name":"By Lamplight","originalName":"燈下","grade":"Moderately Favorable","poem":["Two people sit facing one another by lamplight;","Even silence can feel close.","Speak what rests within your heart,","And the tea will stay warm deep into the night."],"meaning":"Some relationships do not need constant excitement to endure. When it matters, one specific and sincere sentence is more useful than a long stretch of testing and guessing.","action":"Tell someone you trust one clear, unexaggerated truth about how you feel.","quote":"“I can make the tea for you, but I cannot speak the words on your behalf.”"}},{"id":13,"zh-Hant":{"id":13,"name":"止語","grade":"平","poem":["欲言先半步","聽雨落窗紗","不是無話說","留心辨真假"],"meaning":"目前可能有資訊不足、情緒過滿的情況。不是所有提問都需要當場回應，也不是每場爭執都值得參與。","action":"在一件讓你急著表態的事上，先確認最關鍵的事實。","quote":"「不開口，不等於沒立場。」"},"ja":{"name":"言葉を留める","originalName":"止語","grade":"平","poem":["言葉にする前に半歩止まり","雨が窓紗に落ちる音を聴く","語ることがないのではない","真偽を見分ける心を留めよ"],"meaning":"今は情報が足りないか、感情があふれている可能性があります。すべての問いにその場で答える必要はなく、すべての口論に加わる価値があるわけでもありません。","action":"すぐに意見を述べたくなる出来事について、まず最も重要な事実を確認しましょう。","quote":"「口を開かないことと、立場がないことは違う。」"},"en":{"name":"The Unspoken Word","originalName":"止語","grade":"Neutral","poem":["Pause half a step before you speak;","Listen to rain against the window screen.","It is not that you have nothing to say;","Keep your attention on what is true."],"meaning":"There may be too little information, or too much emotion in the room. Not every question needs an immediate answer, and not every argument is worth joining.","action":"When something makes you eager to take a position, first verify the most important fact.","quote":"“Choosing not to speak is not the same as having no position.”"}},{"id":14,"zh-Hant":{"id":14,"name":"回甘","grade":"中吉","poem":["新茶初入口","微苦後回甘","日子非全甜","知味自能安"],"meaning":"有些收穫不是立刻令人愉快，但不代表選擇毫無意義。別過度美化辛苦，也別因一時不順否定整段努力。","action":"辨認目前一件「值得做」與一件「可以放手」的事。","quote":"「茶可以苦，日子不必硬喝到見底。」"},"ja":{"name":"後味","originalName":"回甘","grade":"中吉","poem":["新しい茶を口に含めば","ほのかな苦みのあとに甘みが戻る","日々はすべて甘くはない","味を知れば心も安らぐ"],"meaning":"すぐに楽しいと感じられない成果もありますが、それだけで選択に意味がなかったとは言えません。苦労を美化しすぎず、一時の不調だけで積み重ね全体を否定しないことです。","action":"今の自分にとって「続ける価値のあること」と「手放してよいこと」を一つずつ見分けましょう。","quote":"「茶が苦いことはあっても、人生を底まで飲み干す必要はない。」"},"en":{"name":"The Sweet Aftertaste","originalName":"回甘","grade":"Moderately Favorable","poem":["The first sip of new tea is taken;","A gentle bitterness gives way to sweetness.","Life is not sweet in every moment;","Knowing its taste can bring peace."],"meaning":"Some gains do not feel rewarding right away, but that does not make the choice meaningless. Do not romanticize hardship, and do not dismiss all your effort because of one difficult moment.","action":"Identify one thing worth continuing and one thing you can let go of.","quote":"“Tea may be bitter, but you do not have to force yourself to drink life to the dregs.”"}},{"id":15,"zh-Hant":{"id":15,"name":"山徑","grade":"待時","poem":["山徑多岔路","雲深未見峰","暫歇松陰下","也算趁東風"],"meaning":"資訊還不足以支持一個不可逆的決定。現在適合減少消耗、補上關鍵資訊，而不是用焦慮逼自己選邊。","action":"問自己：做決定前，還缺哪一項可以查證的資訊？","quote":"「迷路時先看地圖，別跟樹吵架。」"},"ja":{"name":"山道","originalName":"山徑","grade":"時を待つ","poem":["山道には分かれ道が多く","雲深く峰はまだ見えない","松の木陰でしばし休もう","それもまた風に乗る道"],"meaning":"取り返しのつかない決断を支えるには、まだ情報が足りません。今は消耗を減らし、重要な情報を補う時です。不安に追い立てられて、無理にどちらかを選ぶ必要はありません。","action":"決断する前に、何を確認できれば判断できるのか、自分に問いかけましょう。","quote":"「道に迷ったら地図を見なさい。木と口論しても道は教えてくれぬ。」"},"en":{"name":"The Mountain Path","originalName":"山徑","grade":"Wait for the Right Time","poem":["The mountain path divides many ways;","Deep clouds hide the summit.","Rest a while beneath the pines;","That, too, is a way of moving with the wind."],"meaning":"There is not yet enough information to support an irreversible decision. This is a time to reduce strain and fill in what is missing, not to let anxiety force you to choose a side.","action":"Ask yourself: what verifiable information is still missing before I can decide?","quote":"“When you are lost, consult a map. Arguing with a tree will not show you the way.”"}},{"id":16,"zh-Hant":{"id":16,"name":"同舟","grade":"吉","poem":["舟行雙槳穩","江闊水無聲","若有同心者","無須步步爭"],"meaning":"合作與親密都不是誰替誰掌舵。彼此知道自己要負什麼責任，遇到不同意見也能繼續向前，這才是真正的同行。","action":"把一項共同的事情講清楚：誰想做、誰願意做。","quote":"「同一條船，不代表要坐同一張椅子。」"},"ja":{"name":"同じ舟","originalName":"同舟","grade":"吉","poem":["二本の櫂で舟は安定し","広い川面に水音はない","心を同じくする人がいるなら","一歩ごとに争う必要はない"],"meaning":"協力も親密さも、どちらかが相手の舵を取ることではありません。それぞれが負う責任を知り、意見が違っても前へ進めることが、本当の同行です。","action":"共同で行うことを一つ選び、誰が望み、誰が何を引き受けるのかを明確にしましょう。","quote":"「同じ舟に乗っているからといって、同じ椅子に座る必要はない。」"},"en":{"name":"In One Boat","originalName":"同舟","grade":"Favorable","poem":["Two oars keep the boat steady;","The broad river makes no sound.","When hearts are willing to travel together,","There is no need to contest every stroke."],"meaning":"Neither cooperation nor intimacy means one person steering for the other. True companionship means each person knows their responsibility and can keep moving even when opinions differ.","action":"Clarify one shared task: who wants it, and who is willing to take responsibility for what.","quote":"“Being in the same boat does not mean you must sit in the same seat.”"}},{"id":17,"zh-Hant":{"id":17,"name":"借光","grade":"中吉","poem":["借得鄰窗火","還明一盞燈","光來無所欠","心定自能行"],"meaning":"接受協助不代表失去自主，也不必把所有好意都當成債。能明白彼此的期待和界線，幫助才會成為幫助。","action":"對一份善意表達感謝，同時確認自己的選擇權。","quote":"「借個火而已，不用把整間屋子押出去。」"},"ja":{"name":"灯を借りる","originalName":"借光","grade":"中吉","poem":["隣家の窓から火を借り","一つの灯をともす","光を受けても借りはない","心が定まれば自ら歩ける"],"meaning":"助けを受けても自分の主体性は失われません。好意をすべて借りとして背負う必要もありません。互いの期待と境界が分かっていれば、助けは本当の助けになります。","action":"受けた親切に感謝を伝えながら、自分で選ぶ権利も確かめておきましょう。","quote":"「火を少し借りただけだ。家一軒を質に入れることはない。」"},"en":{"name":"Borrowed Light","originalName":"借光","grade":"Moderately Favorable","poem":["Borrow a flame from a neighbor’s window;","Let one lamp shine again.","Receiving light does not make you indebted;","With a settled heart, you can walk on."],"meaning":"Accepting help does not mean losing your autonomy, and not every kindness must become a debt. When expectations and boundaries are clear, help can remain what it is meant to be: help.","action":"Thank someone for their kindness while keeping clear your right to make your own choices.","quote":"“You only borrowed a flame. There is no need to put the whole house up as collateral.”"}},{"id":18,"zh-Hant":{"id":18,"name":"守界","grade":"上吉","poem":["庭前留半徑","不礙月來明","門有開關處","方容客往行"],"meaning":"界線不一定使關係疏遠；清楚知道什麼能接受、什麼不能，反而讓靠近變得安心。這是一個適合重新站穩的位置。","action":"對一件不願再勉強自己的事，試著說出簡短而清楚的拒絕。","quote":"「門有門檻，不是要跟客人結仇。」"},"ja":{"name":"境界を守る","originalName":"守界","grade":"上吉","poem":["庭先に半歩の余地を残し","月の光を妨げない","門には開閉の仕組みがあり","それゆえ客も行き来できる"],"meaning":"境界線は必ずしも関係を遠ざけるものではありません。何を受け入れ、何を受け入れないかを明確にすることで、かえって安心して近づけるようになります。今は自分の立ち位置を取り戻すのに適した時です。","action":"これ以上無理をしたくないことについて、短く明確に断る言葉を伝えてみましょう。","quote":"「門に敷居があるからといって、客と喧嘩しているわけではない。」"},"en":{"name":"Keeping Boundaries","originalName":"守界","grade":"Very Favorable","poem":["Leave half a pace of space in the garden;","It does not dim the moon.","A gate must know how to open and close;","Only then can guests come and go."],"meaning":"Boundaries do not necessarily push relationships away. Knowing what you can and cannot accept can make closeness safer. This is a good time to regain your footing.","action":"For something you no longer wish to force yourself to accept, try giving a brief and clear refusal.","quote":"“A threshold at the gate does not mean you are picking a fight with your guest.”"}},{"id":19,"zh-Hant":{"id":19,"name":"新芽","grade":"吉","poem":["簷下小盆栽","昨夜嫩芽開","未聞春有信","先向日光來"],"meaning":"一個微小的新開始正在成形。別因它不夠驚天動地而忽略；真正的改變，常常從沒人注意的一天開始。","action":"替新想法留下最小的可行版本，不急著做到完美。","quote":"「先讓它活，別第一天就要求開花。」"},"ja":{"name":"新芽","originalName":"新芽","grade":"吉","poem":["軒下の小さな鉢植えに","昨夜、新芽が顔を出した","春の便りはまだ届かない","それでも先に陽を向く"],"meaning":"小さな新しい始まりが形になりつつあります。劇的でないからといって見過ごさないでください。本当の変化は、誰も気づかない一日から始まることがあります。","action":"新しい考えに、完璧を求めず、実現できる最小の形を与えましょう。","quote":"「まずは生かしておきなさい。初日から花を咲かせろとは言わぬことだ。」"},"en":{"name":"New Shoots","originalName":"新芽","grade":"Favorable","poem":["In a small pot beneath the eaves,","A tender shoot appeared last night.","No message of spring has arrived,","Yet it has already turned toward the sun."],"meaning":"A small new beginning is taking shape. Do not overlook it because it is not dramatic. Real change often begins on an ordinary day when no one is watching.","action":"Give a new idea its smallest workable form without demanding perfection.","quote":"“Let it live first. Do not demand flowers on its very first day.”"}},{"id":20,"zh-Hant":{"id":20,"name":"迴廊","grade":"平","poem":["迴廊行復返","步步見前庭","若嫌風景舊","何妨換眼睛"],"meaning":"反覆遇到相似情況，不一定是命運故意為難。也可能是習慣的選擇、回應方式或環境條件尚未改變。","action":"找出最近一種反覆發生的模式，只改其中一個環節。","quote":"「一直走同一條廊，當然會看到同一棵樹。」"},"ja":{"name":"回廊","originalName":"迴廊","grade":"平","poem":["回廊を行きつ戻りつし","一歩ごとに中庭が見える","景色が古いと思うなら","見る目を変えてみればよい"],"meaning":"似た状況を繰り返し経験するのは、運命が意地悪をしているからとは限りません。選び方や応じ方、環境の条件がまだ変わっていない可能性もあります。","action":"最近繰り返されているパターンを一つ見つけ、そのうち一つの要素だけを変えてみましょう。","quote":"「同じ回廊を歩き続ければ、同じ木が見えるのは当然だ。」"},"en":{"name":"The Corridor","originalName":"迴廊","grade":"Neutral","poem":["You walk the corridor back and forth;","The courtyard appears at every turn.","If the view seems old to you,","Perhaps it is time to change the way you look."],"meaning":"Repeatedly encountering similar situations does not necessarily mean fate is being cruel. Your habits of choosing or responding, or the conditions around you, may not have changed yet.","action":"Identify one pattern that keeps recurring and change just one part of it.","quote":"“If you keep walking the same corridor, of course you will keep seeing the same tree.”"}},{"id":21,"zh-Hant":{"id":21,"name":"轉潮","grade":"吉","poem":["潮退沙痕現","舟輕可再航","不須追舊浪","自有向前方"],"meaning":"某個階段正在結束，新的空間因此出現。別急著追回所有失去的事物；先看清現在仍握有什麼。","action":"整理一件已經結束的事，留下能帶走的經驗。","quote":"「潮水退了，不用跟海算帳。」"},"ja":{"name":"潮の転じ","originalName":"轉潮","grade":"吉","poem":["潮が引けば砂の跡が現れ","舟は軽くなり再び進める","過ぎた波を追わずとも","前へ向かう道はある"],"meaning":"ある段階が終わり、新しい余地が生まれつつあります。失ったものをすべて取り戻そうと急がず、今も自分の手に残っているものを確かめてください。","action":"すでに終わったことを一つ整理し、そこから持ち帰れる経験を残しましょう。","quote":"「潮が引いたからといって、海に勘定書を突きつける必要はない。」"},"en":{"name":"The Turning Tide","originalName":"轉潮","grade":"Favorable","poem":["When the tide recedes, its traces appear;","The boat grows light enough to sail again.","There is no need to chase the old waves;","A way forward is still there."],"meaning":"One stage is coming to an end, making room for something new. Do not rush to recover everything you have lost. First notice what remains in your hands.","action":"Bring one finished matter to a close and keep the experience you can carry forward.","quote":"“The tide has gone out. There is no need to send the sea an invoice.”"}},{"id":22,"zh-Hant":{"id":22,"name":"尋常","grade":"中吉","poem":["廚煙升小院","茶沸兩三聲","若得尋常日","已是好光景"],"meaning":"當你持續等待戲劇性的證明，可能錯過正在發生的平穩與善意。尋常不是無聊，有時是來之不易的自在。","action":"好好吃一頓飯，留意其中一個你喜歡的細節。","quote":"「沒有大事發生，對某些人就是好消息。」"},"ja":{"name":"いつもの日","originalName":"尋常","grade":"中吉","poem":["小さな庭に炊煙が上がり","茶の沸く音が二、三度","いつもの一日を得られたなら","それだけでよい景色だ"],"meaning":"劇的な証明を待ち続けると、今そこにある穏やかさや善意を見逃すかもしれません。平凡は退屈とは限らず、時には得がたい自由です。","action":"一度きちんと食事をし、その中で好きだと思える細部を一つ見つけましょう。","quote":"「大事が起こらないことが、何よりの知らせになる人もいる。」"},"en":{"name":"An Ordinary Day","originalName":"尋常","grade":"Moderately Favorable","poem":["Cooking smoke rises from the small yard;","The kettle sounds two or three times.","If an ordinary day is yours to keep,","That is already a beautiful scene."],"meaning":"If you keep waiting for dramatic proof, you may miss the steadiness and kindness already present. Ordinary does not mean dull; sometimes it is a hard-won kind of ease.","action":"Eat a proper meal and notice one small detail you enjoy about it.","quote":"“For some people, nothing happening is the best news of all.”"}},{"id":23,"zh-Hant":{"id":23,"name":"歸根","grade":"吉","poem":["枝繁遮遠日","根穩不懼風","欲問何處去","先知所守中"],"meaning":"外界意見很多時，先確認自己真正重視的東西。知道底線與方向，未必能排除所有困難，卻能減少不必要的偏航。","action":"用一句話寫下這次選擇最想守住的原則。","quote":"「知道自己為什麼出門，才不會誰叫都跟著走。」"},"ja":{"name":"根に帰る","originalName":"歸根","grade":"吉","poem":["枝葉が茂り遠い日を覆っても","根が深ければ風を恐れない","どこへ行くべきか問う前に","何を守るかを知ろう"],"meaning":"周囲の意見が多いときほど、自分が本当に大切にしているものを確かめてください。譲れないものと進む方向が分かれば、困難をすべて消せなくても、不要な遠回りは減らせます。","action":"今回の選択で最も守りたい原則を、一文で書きましょう。","quote":"「なぜ出かけたのかを知っていれば、呼ばれるたびについて行かずに済む。」"},"en":{"name":"Returning to the Roots","originalName":"歸根","grade":"Favorable","poem":["Branches may grow thick and hide the distant sun;","Deep roots need not fear the wind.","Before asking where you should go,","Know what you mean to keep."],"meaning":"When outside opinions grow loud, return to what truly matters to you. Knowing your boundaries and direction may not remove every obstacle, but it can keep you from needless detours.","action":"Write one sentence naming the principle you most want to protect in this decision.","quote":"“When you know why you set out, you will not follow every voice that calls.”"}},{"id":24,"zh-Hant":{"id":24,"name":"自明","grade":"上吉","poem":["雲開見遠岑","水定照初心","答案非天授","行來漸自明"],"meaning":"你已經比想像中更接近真正要問的問題。別把籤當成外界替你下的命令；這份明朗，來自你願意承擔自己的選擇。","action":"替目前最重要的決定寫出一個可以在本週實行的下一步。","quote":"「籤解完了，接下來可不能叫貧道替你過日子。」"},"ja":{"name":"おのずと明らかに","originalName":"自明","grade":"上吉","poem":["雲が晴れ遠い峰が見え","水は静まり初心を映す","答えは天から授かるものではない","歩むうちに自ずと明らかになる"],"meaning":"あなたは思っている以上に、本当に問うべきことへ近づいています。籤を、外から命令を下すものにしてはいけません。明晰さは、自分の選択を引き受けようとする姿勢から生まれます。","action":"今もっとも大切な決断について、今週実行できる次の一歩を書き出しましょう。","quote":"「籤の解説はここまでだ。これからの暮らしまで貧道に任せてはならぬ。」"},"en":{"name":"Clarity Within","originalName":"自明","grade":"Very Favorable","poem":["The clouds part; distant peaks appear.","Still water reflects the heart’s first intent.","An answer is not bestowed by heaven;","It becomes clear as you walk."],"meaning":"You may be closer than you think to the question you truly need to ask. Do not treat the lot as an order handed down from outside. Clarity grows from your willingness to take responsibility for your own choice.","action":"For the decision that matters most right now, write down one next step you can take this week.","quote":"“That concludes the reading. You cannot ask me to live the rest of your life for you.”"}},{"id":25,"zh-Hant":{"id":25,"name":"問津","grade":"中吉","category":"感情","poem":["渡頭人未語","春水自東流","欲問同心意","先看共渡舟"],"meaning":"你想確認一段關係能否向前，但心意不能只靠推測。先觀察雙方是否都願意花時間接近，再談下一步。","action":"提出一次具體而輕鬆的邀約，讓對方有自由回應的空間。","quote":"「問對岸願不願過來之前，也得看看兩邊有沒有橋。」"},"ja":{"name":"渡し場を問う","originalName":"問津","grade":"中吉","poem":["渡し場の人はまだ語らず","春の水は東へ流れる","相手の心を知りたいなら","まず同じ舟に乗るかを見よ"],"meaning":"あなたは関係が前へ進むか確かめたいのでしょう。しかし、気持ちは推測だけでは分かりません。次の段階を考える前に、双方が時間をかけて近づこうとしているかを見てください。","action":"相手が自由に返事を選べるよう、具体的で気軽な誘いを一度してみましょう。","quote":"「向こう岸の人が来るか尋ねる前に、両岸に橋があるか確かめなさい。」","category":"恋愛"},"en":{"name":"Asking at the Ferry","originalName":"問津","grade":"Moderately Favorable","poem":["No one speaks at the ferry;","Spring water flows eastward.","If you wish to know another heart,","First see whether you will cross in the same boat."],"meaning":"You want to know whether a relationship can move forward, but feelings cannot be established by guesswork alone. Before considering the next step, observe whether both people are willing to spend time drawing closer.","action":"Make one specific, low-pressure invitation that leaves the other person free to respond.","quote":"“Before asking whether someone on the far shore will come over, check whether there is a bridge between you.”","category":"Love"}},{"id":26,"zh-Hant":{"id":26,"name":"兩岸","grade":"平","category":"感情","poem":["隔岸花同放","潮聲各不同","若求同一步","且問幾時逢"],"meaning":"彼此或許欣賞對方，對關係的期待卻未必一致。感覺相近不等於步調相同，與其逼對方同步，不如說清楚各自的位置。","action":"用不帶質問的方式，問問對方目前對關係的想法。","quote":"「兩岸都開花，不代表得同一天結果。」"},"ja":{"name":"両岸","originalName":"兩岸","grade":"平","poem":["岸を隔てて花はともに咲き","潮の音はそれぞれ違う","同じ歩幅を望むなら","いつ出会えるかを問うてみよ"],"meaning":"互いに好意を持っていても、関係への期待が一致しているとは限りません。気持ちが似ていても歩調は同じとは限らないのです。相手を無理に合わせるより、それぞれの立ち位置を言葉にしましょう。","action":"問い詰める口調にならないように、今の関係をどう考えているか尋ねてみましょう。","quote":"「両岸に花が咲いたからといって、同じ日に実るとは限らぬ。」","category":"恋愛"},"en":{"name":"Two Shores","originalName":"兩岸","grade":"Neutral","poem":["Flowers bloom on both shores;","Yet each hears a different tide.","If you wish to take the same step,","First ask when your paths may meet."],"meaning":"You may admire one another without sharing the same expectations for the relationship. Similar feelings do not guarantee the same pace. Rather than forcing synchronization, make each person’s position clear.","action":"Ask how the other person sees the relationship now, without turning the question into an accusation.","quote":"“Flowers may bloom on both shores, but that does not mean they will bear fruit on the same day.”","category":"Love"}},{"id":27,"zh-Hant":{"id":27,"name":"遇雨","grade":"吉","category":"感情","poem":["雲合行人急","簷低可並肩","雨中誰借傘","情意在其間"],"meaning":"順遂時的好聽話容易說，遇到不便時的態度更能作為參考。這支籤提醒你看見照顧與尊重是否真實存在。","action":"回想一件不順利的時刻，對方曾如何回應你的需要。","quote":"「雨大時誰願意把傘往你那邊挪，這比天晴時說什麼有用。」"},"ja":{"name":"雨に遇う","originalName":"遇雨","grade":"吉","poem":["雲が重なり旅人は急ぐ","低い軒下なら肩を並べられる","雨の中で誰が傘を貸すのか","その間に情が見える"],"meaning":"順調なときには耳に心地よい言葉を誰でも言えます。不便なときの態度のほうが、参考になることがあります。思いやりと尊重が本当にあるかを見てください。","action":"うまくいかなかったとき、相手があなたの必要にどう応じたか、一つ思い返しましょう。","quote":"「雨が強いとき、傘をこちらへ傾けてくれるか。晴れた日に何を言うかより、そのほうが役に立つ。」","category":"恋愛"},"en":{"name":"Meeting the Rain","originalName":"遇雨","grade":"Favorable","poem":["Clouds gather; travelers hurry.","Beneath the low eaves, two can stand side by side.","Who offers an umbrella in the rain?","There, affection reveals itself."],"meaning":"Pleasant words are easy to offer when everything goes well. How someone behaves when things become inconvenient can tell you more. Notice whether care and respect are truly present.","action":"Recall one difficult moment and consider how the other person responded to your needs.","quote":"“When the rain grows heavy, do they tilt the umbrella toward you? That matters more than what they say on a sunny day.”","category":"Love"}},{"id":28,"zh-Hant":{"id":28,"name":"空椅","grade":"待時","category":"感情","poem":["窗邊留一席","日暮少人來","莫把空椅影","當成心底猜"],"meaning":"缺席與沉默可能有許多原因，不能單憑它們認定愛意或惡意。但若長期只有你一個人在等待，也該看看這段關係是否符合自己的需求。","action":"給自己一個合理的等待期限，屆時以實際互動重新評估。","quote":"「椅子空著，不會自己告訴你人去哪了。」"},"ja":{"name":"空席","originalName":"空椅","grade":"時を待つ","poem":["窓辺に席を一つ残し","日暮れにも訪れる人は少ない","空いた椅子の影を","心の中の答えと思うな"],"meaning":"不在や沈黙には、さまざまな理由があり得ます。それだけで好意や悪意を決めつけることはできません。ただし、長い間あなた一人だけが待っているなら、その関係が自分の望みに合っているかも考えてください。","action":"自分にとって無理のない待つ期限を決め、その時点で実際のやり取りをもとに改めて考えましょう。","quote":"「椅子が空いていても、その人がどこへ行ったかまでは教えてくれぬ。」","category":"恋愛"},"en":{"name":"The Empty Chair","originalName":"空椅","grade":"Wait for the Right Time","poem":["One seat remains beside the window;","Few arrive as daylight fades.","Do not mistake the shadow of an empty chair","For an answer from someone’s heart."],"meaning":"Absence and silence can have many causes; neither alone proves affection or ill will. But if you are the only one waiting for a long time, consider whether this relationship meets your needs.","action":"Set a reasonable limit for how long you are willing to wait, then reassess based on what actually happens.","quote":"“An empty chair cannot tell you where the person has gone.”","category":"Love"}},{"id":29,"zh-Hant":{"id":29,"name":"聽潮","grade":"中吉","category":"感情","poem":["潮至沙痕滿","潮回岸石明","往來皆有序","相約聽潮聲"],"meaning":"有些人需要靠近，有些時候需要安靜；親密感不必永遠維持同一濃度。能否談妥聯繫節奏，比猜測每次回訊快慢更重要。","action":"說出自己舒服的聯繫頻率，也聽聽對方的習慣。","quote":"「潮來潮去很正常，別每退一次潮就以為海不見了。」"},"ja":{"name":"潮を聴く","originalName":"聽潮","grade":"中吉","poem":["潮が満ちれば砂の跡を覆い","潮が引けば岸の石が見える","行き来にはそれぞれの時がある","ともに潮の音を聴こう"],"meaning":"近づきたい人もいれば、静かに過ごしたい時もあります。親密さをいつも同じ濃さに保つ必要はありません。返信の速さを推測するより、連絡のペースを話し合えるかが大切です。","action":"自分にとって心地よい連絡の頻度を伝え、相手の習慣にも耳を傾けましょう。","quote":"「潮が満ち引きするのは自然なことだ。引くたびに海が消えたと思わぬように。」","category":"恋愛"},"en":{"name":"Listening to the Tide","originalName":"聽潮","grade":"Moderately Favorable","poem":["The rising tide covers the marks in the sand;","The falling tide reveals stones along the shore.","Coming and going each have their season;","Meet, and listen to the tide together."],"meaning":"Some people need closeness; some moments call for quiet. Intimacy does not have to remain at the same intensity all the time. Being able to discuss a comfortable rhythm matters more than guessing from every reply time.","action":"Share the frequency of contact that feels comfortable to you, and listen to the other person’s habits as well.","quote":"“The tide comes and goes. Do not assume the sea has vanished every time it recedes.”","category":"Love"}},{"id":30,"zh-Hant":{"id":30,"name":"微燈","grade":"吉","category":"感情","poem":["夜半微燈亮","門前步履輕","無言先添水","也待問分明"],"meaning":"體貼可能藏在細小的照應裡，但不能讓行動變成拒絕溝通的藉口。看見對方做了什麼，也要留下確認彼此心意的空間。","action":"對一件具體的照顧表達感謝，再說出自己的真實感受。","quote":"「會替你添水很好；杯子要不要續，還是得問本人。」"},"ja":{"name":"ほのかな灯","originalName":"微燈","grade":"吉","poem":["真夜中に小さな灯がともり","門前の足音は静か","言葉なく先に水を注ぎ","それでも心は確かめよう"],"meaning":"思いやりは、ささやかな気遣いの中に隠れていることがあります。しかし、行動をコミュニケーションを避ける口実にしてはいけません。相手の行動に気づきながら、互いの気持ちを確かめる余地も残しましょう。","action":"具体的な気遣いに感謝を伝えたうえで、自分の本当の気持ちも話しましょう。","quote":"「水を注いでくれるのはありがたい。おかわりするかどうかは、本人に聞くことだ。」","category":"恋愛"},"en":{"name":"A Small Light","originalName":"微燈","grade":"Favorable","poem":["A small lamp glows at midnight;","Footsteps pass softly by the gate.","Water is poured before a word is spoken;","Still, let the heart be asked and understood."],"meaning":"Care can be found in small gestures. But actions should not become an excuse to avoid communication. Notice what the other person does, while leaving room to confirm how you both feel.","action":"Thank the other person for a specific act of care, then share what you genuinely feel.","quote":"“It is kind of you to refill someone’s cup. Whether they want more is still something you should ask.”","category":"Love"}},{"id":31,"zh-Hant":{"id":31,"name":"放手","grade":"上吉","category":"感情","poem":["舊線纏衣袖","開結見晴空","從今輕放手","不負一庭風"],"meaning":"放開一段反覆消耗的關係，不等於否定過去曾經的真心。你可以珍惜回憶，也選擇不再讓自己困在同一個結裡。","action":"停止一項讓自己反覆受傷的聯繫或查看習慣。","quote":"「結解不開就先別勒著手，衣袖也不是命根子。」"},"ja":{"name":"手放す","originalName":"放手","grade":"上吉","poem":["古い糸が袖に絡みつく","結び目を解けば空が見える","これからはそっと手を放し","庭を渡る風を拒まぬように"],"meaning":"何度も自分をすり減らす関係を手放しても、かつての真心まで否定することにはなりません。思い出を大切にしながら、同じ結び目に自分を閉じ込めない選択もできます。","action":"自分を何度も傷つける連絡や確認の習慣を、一つやめてみましょう。","quote":"「結び目がほどけぬなら、まず手を締めつけるのをやめなさい。袖は命より大切なものではない。」","category":"恋愛"},"en":{"name":"Letting Go","originalName":"放手","grade":"Very Favorable","poem":["An old thread tangles around your sleeve;","Untie the knot, and the sky appears.","From this day, let your hand open gently;","Do not turn away the wind crossing the garden."],"meaning":"Letting go of a relationship that repeatedly wears you down does not invalidate the sincerity you once felt. You can treasure the memories and still choose not to remain trapped in the same knot.","action":"Stop one habit of contact or checking that repeatedly hurts you.","quote":"“If the knot will not loosen, stop tightening your hand around it. A sleeve is not your life.”","category":"Love"}},{"id":32,"zh-Hant":{"id":32,"name":"共簷","grade":"吉","category":"婚姻","poem":["一簷承細雨","兩盞各溫茶","共住須商量","方能稱作家"],"meaning":"共同生活不是把兩個人揉成一個人，而是一起決定怎麼住、怎麼分工、怎麼相處。願意協商，屋簷下才有彼此的位置。","action":"挑一件日常家務，討論雙方真正願意承擔的部分。","quote":"「同住一個屋簷，總不能連誰倒垃圾都靠天意。」"},"ja":{"name":"同じ軒の下","originalName":"共簷","grade":"吉","poem":["一つの軒が細雨を受け","二つの茶碗はそれぞれ温かい","共に住むなら話し合い","それで初めて家と呼べる"],"meaning":"共同生活とは、二人を一つに溶かすことではありません。住み方、家事の分担、日々の過ごし方を一緒に決めることです。話し合う意思があってこそ、同じ屋根の下に双方の居場所ができます。","action":"日々の家事を一つ選び、双方が本当に引き受けられる範囲を話し合いましょう。","quote":"「同じ屋根の下に住むのに、誰がごみを出すかまで天に任せるわけにはいかぬ。」","category":"結婚"},"en":{"name":"Under One Roof","originalName":"共簷","grade":"Favorable","poem":["One roof receives the gentle rain;","Two cups of tea are warmed separately.","To live together, one must talk and agree;","Only then can it truly be called home."],"meaning":"Living together does not mean blending two people into one. It means deciding together how to live, divide chores, and share daily life. A home has room for both people when they are willing to negotiate.","action":"Choose one household task and discuss what each person is genuinely willing to take on.","quote":"“If you share a roof, you cannot leave even taking out the trash to the heavens.”","category":"Marriage"}},{"id":33,"zh-Hant":{"id":33,"name":"分房","grade":"平","category":"婚姻","poem":["兩室燈分照","中庭共月明","門開皆自在","不必問疏親"],"meaning":"個人空間與親密不是對立的選項。休息方式不同時，先協調習慣，不必以房門是否關上衡量感情深淺。","action":"確認各自需要的獨處時間和可以共同使用的空間。","quote":"「門關著是要休息，不一定是在演八點檔。」"},"ja":{"name":"別々の部屋","originalName":"分房","grade":"平","poem":["二つの部屋に灯がともり","中庭には同じ月が昇る","扉を開けても閉じても自在","親しさを問いただす必要はない"],"meaning":"個人の空間と親密さは、対立するものではありません。休み方が違うなら、まず習慣を調整しましょう。扉が閉まっているかどうかで、愛情の深さを測る必要はありません。","action":"それぞれに必要な一人の時間と、共有できる空間を確認しましょう。","quote":"「扉が閉まっているのは休みたいからかもしれぬ。昼の連続ドラマを演じているとは限らぬ。」","category":"結婚"},"en":{"name":"Separate Rooms","originalName":"分房","grade":"Neutral","poem":["Two rooms hold their own lamplight;","The same moon shines over the courtyard.","A door may open or close freely;","There is no need to measure affection by it."],"meaning":"Personal space and intimacy are not opposites. If your ways of resting differ, begin by negotiating your habits. A closed door is not a measure of how deeply someone cares.","action":"Clarify how much time each person needs alone and which spaces can be shared.","quote":"“A closed door may simply mean someone wants to rest. It does not have to be a scene from a soap opera.”","category":"Marriage"}},{"id":34,"zh-Hant":{"id":34,"name":"議約","grade":"中吉","category":"婚姻","poem":["合約攤燈下","兩人細細看","條文須問透","落筆始心安"],"meaning":"承諾的價值在於雙方明白內容並自願承擔，而不是誰先點頭就算誰輸。重大安排要有充分討論，也要容許修改。","action":"把一項未說清的共同承諾寫下來，確認雙方理解是否相同。","quote":"「字都還沒看完就簽，貧道看了也會先拿眼鏡。」"},"ja":{"name":"約束を交わす","originalName":"議約","grade":"中吉","poem":["契約書を灯の下に広げ","二人で細かく目を通す","条文は最後まで確かめ","筆を入れて初めて心が安らぐ"],"meaning":"約束の価値は、双方が内容を理解し、自分の意思で引き受けることにあります。先にうなずいたほうが負け、という話ではありません。大切な取り決めには十分な話し合いと、必要に応じて変更できる余地が必要です。","action":"曖昧なままになっている共同の約束を一つ書き出し、双方の理解が一致しているか確認しましょう。","quote":"「字を読み終える前に署名するとは。貧道でさえ、まず眼鏡を探す。」","category":"結婚"},"en":{"name":"Terms of Agreement","originalName":"議約","grade":"Moderately Favorable","poem":["Lay the agreement beneath the lamp;","Let both people read each line.","Question every clause until it is clear;","Only then may the pen bring peace."],"meaning":"The value of a commitment lies in both people understanding it and accepting it willingly. It is not a contest in which the first person to agree loses. Important arrangements need discussion and room for revision.","action":"Write down one shared commitment that remains unclear and check whether you both understand it the same way.","quote":"“Signing before reading the whole thing? Even I would reach for my glasses first.”","category":"Marriage"}},{"id":35,"zh-Hant":{"id":35,"name":"飯香","grade":"吉","category":"婚姻","poem":["小院炊煙起","青蔬上晚盤","有人分碗筷","平日亦成歡"],"meaning":"長久相處往往靠許多看似普通的行動累積。若彼此能把日常照顧當成共同責任，親近便有實際的根。","action":"為兩人安排一件不費力、卻能共同完成的生活小事。","quote":"「感情不是只靠燭光晚餐，洗碗槽也很有發言權。」"},"ja":{"name":"炊事の香り","originalName":"飯香","grade":"吉","poem":["小さな庭に炊煙が立ち","夕餉の皿に青菜が並ぶ","誰かが箸と茶碗を分け合えば","何気ない日も喜びとなる"],"meaning":"長く続く関係は、ありふれた行動の積み重ねによって育つことがよくあります。日々の世話を双方の責任として分かち合えれば、親しさには確かな根ができます。","action":"二人で無理なくできる、暮らしの小さな用事を一つ計画しましょう。","quote":"「愛情はキャンドルディナーだけで成り立つものではない。流し台にも言い分がある。」","category":"結婚"},"en":{"name":"The Scent of Supper","originalName":"飯香","grade":"Favorable","poem":["Cooking smoke rises from the little yard;","Greens are set upon the evening plate.","When someone shares bowls and chopsticks,","An ordinary day becomes a joy."],"meaning":"Lasting relationships are often built through many ordinary acts. When both people treat everyday care as a shared responsibility, closeness gains practical roots.","action":"Plan one small, manageable everyday task that the two of you can do together.","quote":"“A relationship cannot live on candlelit dinners alone. The kitchen sink has a say, too.”","category":"Marriage"}},{"id":36,"zh-Hant":{"id":36,"name":"客至","grade":"待時","category":"婚姻","poem":["堂前賓客滿","席上話家門","莫借親情字","來遮兩意真"],"meaning":"親友的期待可能出於好意，也可能無意間壓過當事人的意願。婚姻裡真正重要的安排，仍應由共同生活的人決定。","action":"先和伴侶談妥一項對外界要求的共同回應方式。","quote":"「長輩能來喝喜酒，不能順便接管你們的日曆。」"},"ja":{"name":"客人の訪れ","originalName":"客至","grade":"時を待つ","poem":["座敷には客人が満ち","席では家の話が続く","親族という言葉を借りて","二人の本心を覆ってはならぬ"],"meaning":"親しい人々の期待は善意から来ることもありますが、当事者の意思を無意識に押しのけることもあります。結婚生活の大切な取り決めは、共に暮らす二人が決めるべきです。","action":"周囲からの要望にどう応じるか、まずパートナーと共通の返答を決めておきましょう。","quote":"「年長者は祝いの席に来てよい。だが、ついでに二人の予定表まで管理する必要はない。」","category":"結婚"},"en":{"name":"When Guests Arrive","originalName":"客至","grade":"Wait for the Right Time","poem":["The hall is full of guests;","Family matters fill the table talk.","Do not use the name of kinship","To cover what the two of you truly feel."],"meaning":"Expectations from family and friends may come from good intentions, yet they can also unintentionally override the wishes of those involved. Important decisions in a marriage should belong to the people who share that life.","action":"First agree with your partner on how you will respond together to an outside request.","quote":"“Elders are welcome at the wedding feast. They do not need to take over your calendar as well.”","category":"Marriage"}},{"id":37,"zh-Hant":{"id":37,"name":"同桌","grade":"中吉","category":"婚姻","poem":["茶案分雙座","言殊尚可談","無須先認錯","理清再共擔"],"meaning":"發生分歧不表示關係失敗，反倒是看見彼此需要的機會。把問題講清楚，比急著爭誰比較有道理更能帶來改變。","action":"選一件小分歧，先各自說明需求，再討論可能的做法。","quote":"「同桌吃飯，也不必連鹹淡都投票決定。」"},"ja":{"name":"同じ卓","originalName":"同桌","grade":"中吉","poem":["茶卓には二つの席","言葉が違っても話はできる","先に謝る必要はない","筋道を整えてから共に担おう"],"meaning":"意見の違いは関係の失敗を意味しません。むしろ互いの必要に気づく機会です。誰が正しいかを急いで争うより、問題を明確にするほうが変化につながります。","action":"小さな意見の違いを一つ選び、まず双方の必要を説明し合ってから、できる方法を話し合いましょう。","quote":"「同じ卓で食事をしても、塩加減まで投票で決める必要はない。」","category":"結婚"},"en":{"name":"At the Same Table","originalName":"同桌","grade":"Moderately Favorable","poem":["Two places are set at the tea table;","Different words can still meet in conversation.","There is no need to apologize first;","Understand the matter, then carry it together."],"meaning":"Disagreement does not mean a relationship has failed. It can reveal what each person needs. Clarifying the problem is more likely to bring change than rushing to prove who is right.","action":"Choose one minor disagreement. First explain what each person needs, then discuss possible ways forward.","quote":"“You may share a table without holding a vote on how salty the food should be.”","category":"Marriage"}},{"id":38,"zh-Hant":{"id":38,"name":"舊帖","grade":"平","category":"婚姻","poem":["舊帖藏箱底","紅封已褪光","前人留此約","未必定今朝"],"meaning":"上一代的約定、家族的習慣，可能有其歷史，卻不必全盤成為你今日的責任。尊重傳統，可以與重新選擇並存。","action":"分辨一件家族期待：哪些是自己的心願，哪些只是習慣承接。","quote":"「老契約值得保存，不代表每張都還能拿來用。」"},"ja":{"name":"古い約束","originalName":"舊帖","grade":"平","poem":["古い書付は箱の底","赤い封は色あせた","先人が残した約束も","今日を決めるとは限らない"],"meaning":"前の世代の約束や家族の習慣には歴史があるかもしれませんが、すべてを今の自分の責任にする必要はありません。伝統を尊重することと、新しく選び直すことは両立します。","action":"家族からの期待を一つ取り上げ、自分の願いなのか、ただ受け継いだ習慣なのかを見分けましょう。","quote":"「古い契約を保存する価値はある。だが、どの契約も今なお使えるとは限らぬ。」","category":"結婚"},"en":{"name":"The Old Deed","originalName":"舊帖","grade":"Neutral","poem":["An old deed rests at the bottom of a box;","Its red seal has faded.","A promise left by those before us","Does not necessarily decide today."],"meaning":"Agreements made by earlier generations and family customs may carry history, but they do not all have to become your responsibility today. Respecting tradition can coexist with making a new choice.","action":"Take one family expectation and distinguish what you truly want from what you have simply inherited as a habit.","quote":"“An old contract may be worth preserving. That does not mean every clause is still in force.”","category":"Marriage"}},{"id":39,"zh-Hant":{"id":39,"name":"並肩","grade":"上吉","category":"婚姻","poem":["同路非牽繩","行時各有聲","並肩看遠樹","今後共商程"],"meaning":"最珍貴的同行不是被迫留在一起，而是兩人都知道仍有選擇，卻願意一起往前。維持自主與互相照應，並不矛盾。","action":"和重要的人談一件雙方都期待的未來安排。","quote":"「並肩走路不是綁腳比賽，走得穩就好。」"},"ja":{"name":"肩を並べて","originalName":"並肩","grade":"上吉","poem":["同じ道を行くことは綱で縛ることではない","歩けばそれぞれの声がある","肩を並べて遠くの木を眺め","これからの道を共に相談しよう"],"meaning":"最も尊い同行とは、無理に一緒に留まることではありません。二人とも選ぶ自由があると知りながら、それでも共に進むことです。自立と支え合いは矛盾しません。","action":"大切な人と、双方が楽しみにできる未来の予定を一つ話し合いましょう。","quote":"「肩を並べて歩くのは、足を縛り合う競争ではない。安定して歩ければよい。」","category":"結婚"},"en":{"name":"Side by Side","originalName":"並肩","grade":"Very Favorable","poem":["To share a road is not to be tied by a rope;","Each has a voice while walking.","Stand side by side and look toward distant trees;","Discuss the road that lies ahead."],"meaning":"The most meaningful companionship is not being forced to stay together. It is choosing to move forward together while knowing that each person remains free to choose. Independence and mutual care are not opposites.","action":"Discuss one future plan with someone important to you—something both of you can look forward to.","quote":"“Walking side by side is not a contest to tie each other’s feet. A steady pace is enough.”","category":"Marriage"}},{"id":40,"zh-Hant":{"id":40,"name":"過橋","grade":"吉","category":"人際","poem":["橋斷留殘木","修時須兩端","若無人願渡","何必獨憑欄"],"meaning":"關係有機會修復，但不能只靠一個人不斷彌補。若雙方願意承認問題、重新安排互動，橋才真正能通。","action":"先確認對方是否也願意溝通，不急著獨自承擔修復工作。","quote":"「橋要接兩岸，總不能叫一岸把木頭一路扛過去。」"},"ja":{"name":"橋を渡る","originalName":"過橋","grade":"吉","poem":["橋は崩れ残る木だけ","直すなら両岸から","渡ろうとする人がいないなら","一人で欄干にもたれる必要はない"],"meaning":"関係を修復できる可能性はありますが、一人が何度も埋め合わせるだけでは成り立ちません。双方が問題を認め、関わり方を改める意思を持って初めて、橋は通れるようになります。","action":"自分だけで修復を背負う前に、相手にも話し合う意思があるかを確かめましょう。","quote":"「橋は両岸をつなぐものだ。一方の岸だけに木材を運ばせるわけにはいかぬ。」","category":"人間関係"},"en":{"name":"Crossing the Bridge","originalName":"過橋","grade":"Favorable","poem":["The bridge has fallen, leaving only a few timbers;","Repairs must begin on both shores.","If no one is willing to cross,","Why lean alone against the railing?"],"meaning":"A relationship may be repairable, but not if one person must keep making up for everything. The bridge can be crossed only when both sides are willing to acknowledge the problem and change how they relate.","action":"Before taking responsibility for repairing everything yourself, find out whether the other person is also willing to talk.","quote":"“A bridge connects two shores. You cannot ask one shore to carry all the timber.”","category":"Relationships"}},{"id":41,"zh-Hant":{"id":41,"name":"量尺","grade":"平","category":"人際","poem":["木尺量高低","人情難一齊","各言何處止","才免踏淤泥"],"meaning":"你與對方對玩笑、距離、付出的標準可能不同。與其期待別人自動懂得分寸，不如清楚表達，再看對方如何回應。","action":"挑一條最重要的界線，用具體例子向對方說明。","quote":"「每個人拿的尺不一樣，先別急著說別人量錯。」"},"ja":{"name":"物差し","originalName":"量尺","grade":"平","poem":["木の物差しで高さを測る","人の情は同じには測れない","それぞれどこで止まるかを語れば","泥濘を踏まずに済む"],"meaning":"冗談、距離、尽くし方について、あなたと相手の基準は違うかもしれません。相手が自動的に察してくれると期待するより、はっきり伝え、その後どう応じるかを見ることです。","action":"最も大切な境界線を一つ選び、具体例を使って相手に説明しましょう。","quote":"「人はそれぞれ違う物差しを持つ。すぐに相手の測り方が間違いだと言わぬことだ。」","category":"人間関係"},"en":{"name":"The Measure","originalName":"量尺","grade":"Neutral","poem":["A wooden ruler measures height;","Human feeling is harder to measure alike.","Say where each person draws the line,","And you may avoid the mud."],"meaning":"You and the other person may have different standards for humor, distance, and effort. Rather than expecting them to understand your limits automatically, state them clearly and observe how they respond.","action":"Choose one important boundary and explain it to the other person with a concrete example.","quote":"“Everyone carries a different ruler. Do not be so quick to declare someone else’s measurement wrong.”","category":"Relationships"}},{"id":42,"zh-Hant":{"id":42,"name":"失約","grade":"待時","category":"人際","poem":["空簷鐘又響","約定久無聲","莫信窗前影","還看來日行"],"meaning":"偶爾失約需要了解原因，反覆失約則值得觀察模式。比起反覆猜想對方心意，行為是否改善更能提供判斷依據。","action":"記下最近一項承諾是否兌現，必要時重新約定期限。","quote":"「鬧鐘響過三次，跟有沒有起床還是兩回事。」"},"ja":{"name":"約束違い","originalName":"失約","grade":"時を待つ","poem":["軒下の鐘がまた鳴る","約束は長く声を失った","窓辺の影を信じず","明日からの行いを見よ"],"meaning":"一度の約束違いには事情を確かめる必要があります。何度も繰り返されるなら、そのパターンを観察してください。相手の気持ちを推測し続けるより、行動が変わるかどうかのほうが判断材料になります。","action":"最近の約束が守られたか記録し、必要なら期限を改めて取り決めましょう。","quote":"「目覚ましが三度鳴ったことと、実際に起きたことは別の話だ。」","category":"人間関係"},"en":{"name":"A Broken Promise","originalName":"失約","grade":"Wait for the Right Time","poem":["The bell beneath the eaves rings again;","The promise has long fallen silent.","Do not trust the shadow at the window;","Look instead at what happens from tomorrow on."],"meaning":"An occasional broken promise deserves an explanation. Repeated failures deserve attention to the pattern. Whether behavior changes is a more reliable guide than endlessly guessing what the other person feels.","action":"Keep track of whether a recent commitment was fulfilled, and renegotiate the deadline if needed.","quote":"“An alarm ringing three times and someone actually getting up are two different things.”","category":"Relationships"}},{"id":43,"zh-Hant":{"id":43,"name":"茶冷","grade":"平","category":"人際","poem":["茶涼杯尚在","人去院初靜","欲問何時返","先聽自心聲"],"meaning":"關係有時會慢慢改變，並非每一次疏遠都需要找到誰對誰錯。先承認自己的感受，再決定是否有必要重新聯繫。","action":"想想你是想念這個人，還是想念當時相處的方式。","quote":"「茶冷了可以再泡，倒是不必追著每個客人問怎麼不喝。」"},"ja":{"name":"冷めた茶","originalName":"茶冷","grade":"平","poem":["茶は冷めても杯は残り","人が去り庭は静まる","いつ戻るのか尋ねる前に","まず自分の心の声を聴け"],"meaning":"関係は少しずつ変わることがあります。距離ができるたびに、誰が正しく誰が悪いかを決める必要はありません。まず自分の感情を認め、再び連絡する必要があるかを考えましょう。","action":"その人自身が恋しいのか、それとも当時の付き合い方が恋しいのかを考えてみましょう。","quote":"「茶はまた淹れられる。飲まない客を追いかけて理由を聞く必要はない。」","category":"人間関係"},"en":{"name":"Cooled Tea","originalName":"茶冷","grade":"Neutral","poem":["The tea has cooled, but the cup remains;","Someone has left, and the garden grows quiet.","Before asking when they will return,","Listen first to your own heart."],"meaning":"Relationships sometimes change gradually. Every growing distance does not require a verdict on who was right or wrong. First acknowledge your own feelings, then decide whether reconnecting is necessary.","action":"Ask yourself whether you miss the person, or the way things used to feel between you.","quote":"“Tea can always be brewed again. You need not chase every guest who leaves theirs untouched.”","category":"Relationships"}},{"id":44,"zh-Hant":{"id":44,"name":"新識","grade":"中吉","category":"人際","poem":["陌路逢微笑","相邀過短亭","花期未可料","先聽各方音"],"meaning":"新的相識帶來可能，也需要時間辨認彼此的個性與邊界。慢慢累積共同經驗，比急著給關係下定義更可靠。","action":"在下一次交流時，多問一個真正想了解的小問題。","quote":"「才喝第一杯茶，不必連下次家宴的座位都安排好。」"},"ja":{"name":"新たな出会い","originalName":"新識","grade":"中吉","poem":["見知らぬ道で微笑みに出会い","短い亭へと誘われる","花の盛りはまだ分からない","まずは互いの声を聴こう"],"meaning":"新しい出会いには可能性がありますが、互いの性格や境界を知るには時間が必要です。関係に早く名前をつけるより、共に過ごした経験を少しずつ重ねるほうが確かです。","action":"次に話すとき、本当に知りたいことを一つ多く尋ねてみましょう。","quote":"「茶を一杯飲んだばかりで、次の家族宴席の席順まで決める必要はない。」","category":"人間関係"},"en":{"name":"A New Acquaintance","originalName":"新識","grade":"Moderately Favorable","poem":["A smile appears along an unfamiliar road;","An invitation leads to a little pavilion.","No one yet knows when the flowers will bloom;","First, listen to one another."],"meaning":"A new acquaintance brings possibility, but it takes time to understand each other’s nature and boundaries. Gradually building shared experiences is more reliable than rushing to define the relationship.","action":"In your next conversation, ask one additional question you genuinely want to know the answer to.","quote":"“You have only shared one cup of tea. There is no need to plan the seating chart for the next family banquet.”","category":"Relationships"}},{"id":45,"zh-Hant":{"id":45,"name":"門燈","grade":"中吉","category":"家宅","poem":["巷尾一燈暖","風寒尚可歸","家門非血脈","相安便是依"],"meaning":"家不一定只由血緣或法律關係定義。能否讓人安心、容納不同需要，才是這支籤提醒你留意的根本。","action":"為自己的生活角落添一樣能帶來安定感的小物或習慣。","quote":"「門牌上寫誰的姓，跟屋裡能不能好好睡覺是兩回事。」"},"ja":{"name":"門灯","originalName":"門燈","grade":"中吉","poem":["路地の奥に灯がともり","寒風の夜にも帰る場所がある","家の門は血筋だけではない","安らかに暮らせることが支えとなる"],"meaning":"家は血縁や法律上の関係だけで決まるものではありません。安心できるか、異なる必要を受け入れられるか。そのことに目を向けてください。","action":"自分の生活空間に、安心感をもたらす小物や習慣を一つ加えましょう。","quote":"「表札に誰の姓があるかと、家の中で安心して眠れるかは別の話だ。」","category":"家庭・住まい"},"en":{"name":"The Doorway Lamp","originalName":"門燈","grade":"Moderately Favorable","poem":["A warm lamp glows at the end of the lane;","Even in the cold wind, there is a place to return.","A home is not defined by blood alone;","Peace between its people is what makes it shelter."],"meaning":"Home is not defined solely by blood ties or legal relationships. What matters is whether people can feel safe there and whether different needs can be accommodated.","action":"Add one small object or habit to your living space that helps you feel settled.","quote":"“Whose surname is on the doorplate is one thing; whether you can sleep peacefully inside is another.”","category":"Home & Family"}},{"id":46,"zh-Hant":{"id":46,"name":"簷漏","grade":"平","category":"家宅","poem":["屋漏逢新雨","盆多未治根","若圖今夜靜","明日又留痕"],"meaning":"把眼前的不便遮掩起來，未必解決真正的問題。無論是家務、設備還是相處摩擦，都值得從源頭修補。","action":"列出家中一件反覆發生的問題，找出可以處理的根本原因。","quote":"「拿十個盆接雨很勤勞，但屋頂還是破的。」"},"ja":{"name":"雨漏り","originalName":"簷漏","grade":"平","poem":["屋根の漏れに新たな雨","水受けの鉢は増えるばかり","今夜だけ静かにしようとしても","明日にはまた跡が残る"],"meaning":"目の前の不便を覆い隠すだけでは、根本的な解決にならないことがあります。家事、設備、あるいは人との摩擦も、原因から修繕する価値があります。","action":"家の中で繰り返し起きる問題を一つ挙げ、根本原因に対処できる方法を探しましょう。","quote":"「雨を受ける鉢を十個並べても、屋根に穴が開いたままでは意味がない。」","category":"家庭・住まい"},"en":{"name":"The Leaking Eaves","originalName":"簷漏","grade":"Neutral","poem":["New rain falls through the leaking roof;","More bowls are set out to catch it.","If you only seek quiet for tonight,","Tomorrow will leave another stain."],"meaning":"Covering up an inconvenience may not solve the underlying problem. Whether it concerns chores, equipment, or friction between people, it is worth repairing the cause rather than only the symptom.","action":"List one recurring problem at home and look for a way to address its underlying cause.","quote":"“Ten bowls may catch the rain, but the roof will still be broken.”","category":"Home & Family"}},{"id":47,"zh-Hant":{"id":47,"name":"祖席","grade":"待時","category":"家宅","poem":["長席排高位","杯中盡舊恩","敬茶非領命","言止自有門"],"meaning":"家族中的禮數與親情值得珍惜，但感謝不能被當成無條件服從。你有權決定哪些事情由自己承擔。","action":"為下一次家族請託準備一句有禮而明確的回應。","quote":"「敬杯茶是禮貌，不是交出自己人生的印章。」"},"ja":{"name":"祖先の席","originalName":"祖席","grade":"時を待つ","poem":["長い席には上座が並び","杯には昔からの恩が満ちる","茶を敬って差し出すことは命令を受けることではない","言葉を止めるにも自分の門がある"],"meaning":"家族の礼儀や情は大切にしてよいものです。しかし、感謝を無条件の服従として扱わせてはいけません。何を自分が引き受けるかは、自分で決める権利があります。","action":"次に家族から頼まれごとをされたときのために、礼儀正しく明確な返答を一つ用意しましょう。","quote":"「茶を一杯差し出すのは礼儀だ。自分の人生の印章を渡すことではない。」","category":"家庭・住まい"},"en":{"name":"The Ancestral Seat","originalName":"祖席","grade":"Wait for the Right Time","poem":["The long table is arranged with places of honor;","Old debts of gratitude fill the cups.","Offering tea with respect is not accepting an order;","Even silence has a gate of its own."],"meaning":"Family customs and affection may be worth cherishing. But gratitude should not be turned into unconditional obedience. You have the right to decide what you will take responsibility for.","action":"Prepare one polite but clear response for the next time a family member asks something of you.","quote":"“Offering a cup of tea is courtesy. It is not handing over the seal of your life.”","category":"Home & Family"}},{"id":48,"zh-Hant":{"id":48,"name":"一窗","grade":"吉","category":"家宅","poem":["同窗看暮色","各賞不同雲","不必求齊眼","仍能共守門"],"meaning":"同一個家裡的人可以有不同看法，彼此不必事事一致才算相愛。讓分歧有地方安放，生活才不會變成辯論賽。","action":"和家人談一個彼此看法不同、但不需要爭輸贏的小話題。","quote":"「一扇窗看出去，左邊的人看樹，右邊的人看雲，都沒違法。」"},"ja":{"name":"一つの窓","originalName":"一窗","grade":"吉","poem":["同じ窓から夕暮れを眺め","それぞれ違う雲を見つける","同じ見方を求めなくても","ともに門を守ることはできる"],"meaning":"同じ家に暮らす人々にも、それぞれ違う考えがあります。すべてが一致しなければ愛情がない、ということではありません。意見の違いを置いておける場所があれば、暮らしは議論の場にならずに済みます。","action":"家族と、勝ち負けを決める必要のない小さな話題について話してみましょう。","quote":"「同じ窓を見ても、左の人は木を、右の人は雲を見る。それで何の問題もない。」","category":"家庭・住まい"},"en":{"name":"One Window","originalName":"一窗","grade":"Favorable","poem":["They watch the dusk through one window;","Each sees a different cloud.","They need not see everything alike","To keep the same door together."],"meaning":"People in the same home can hold different views. Love does not require agreement on everything. When there is room for disagreement, daily life need not become a permanent debate.","action":"Talk with a family member about one small topic where no one needs to win.","quote":"“Through the same window, one person sees a tree and another sees a cloud. Neither has done anything wrong.”","category":"Home & Family"}},{"id":49,"zh-Hant":{"id":49,"name":"新炊","grade":"上吉","category":"家宅","poem":["新灶初生火","碗盤次第安","添柴非一日","暖意遍庭間"],"meaning":"新的居住方式或生活秩序正在建立。你不需要一次把一切做到完美，能持續維護的小習慣，會慢慢帶來踏實感。","action":"為新生活設定一項簡單、可持續的每日例行事。","quote":"「新家不是靠開箱影片住起來的，還是得有人記得買米。」"},"ja":{"name":"炊きたて","originalName":"新炊","grade":"上吉","poem":["新しい竈に火がともり","器は一つずつ整えられる","薪を足すのは一日ではない","温もりは庭じゅうに広がる"],"meaning":"新しい住まい方や生活の秩序が築かれつつあります。すべてを一度に完璧にする必要はありません。続けられる小さな習慣が、少しずつ確かな安心をもたらします。","action":"新しい暮らしのために、簡単で続けやすい毎日の習慣を一つ決めましょう。","quote":"「新居は開封動画だけでは住めるようにならぬ。米を買う人も必要だ。」","category":"家庭・住まい"},"en":{"name":"Freshly Cooked Rice","originalName":"新炊","grade":"Very Favorable","poem":["A new hearth catches its first flame;","The bowls are set in their places.","A fire is not fed in a single day;","Its warmth slowly fills the courtyard."],"meaning":"A new way of living or a new daily order is taking shape. You do not need to make everything perfect at once. Small habits you can sustain will gradually create a sense of stability.","action":"Set one simple, sustainable daily routine for your new way of living.","quote":"“A new home does not become livable through an unboxing video. Someone still has to remember to buy rice.”","category":"Home & Family"}},{"id":50,"zh-Hant":{"id":50,"name":"遷居","grade":"平","category":"家宅","poem":["舊屋門邊樹","新街路未平","行囊須細算","何處可安身"],"meaning":"換一個住處有新的可能，也可能帶來費用、交通與生活習慣上的調整。喜不喜歡一個地方，還需要看它能否支持你的日常。","action":"列出搬遷最重要的三項條件，實際比較而不只憑想像。","quote":"「風景好看是一回事，半夜買不買得到衛生紙又是另一回事。」"},"ja":{"name":"住まいを移す","originalName":"遷居","grade":"平","poem":["古い家のそばに木があり","新しい町の道はまだ平らでない","荷物と費用を細かく数え","どこなら身を落ち着けられるか"],"meaning":"住まいを変えることには新しい可能性がありますが、費用、交通、生活習慣の調整も伴います。その場所が好きかどうかだけでなく、日々の暮らしを支えてくれるかを見ましょう。","action":"引っ越しで最も大切な条件を三つ挙げ、想像だけでなく実際に比較しましょう。","quote":"「景色が美しいのはよいことだ。だが、夜中にトイレットペーパーが買えるかは別の話だ。」","category":"家庭・住まい"},"en":{"name":"Moving House","originalName":"遷居","grade":"Neutral","poem":["A tree stands beside the old house;","The roads in the new town are still unfamiliar.","Count your belongings and costs with care;","Where can you truly settle?"],"meaning":"Moving may bring new possibilities, but it also means adjusting to costs, transportation, and daily habits. Look beyond whether you like a place; consider whether it can support your everyday life.","action":"List the three most important conditions for a move and compare them in practical terms, not only in imagination.","quote":"“A beautiful view is one thing. Whether you can buy toilet paper in the middle of the night is another.”","category":"Home & Family"}},{"id":51,"zh-Hant":{"id":51,"name":"掃庭","grade":"中吉","category":"家宅","poem":["晨掃階前葉","風來又滿庭","不嫌日日做","慢使院中清"],"meaning":"整理不是一次性的成果，而是與生活持續協調。別因事情做完又出現就否定努力，也可以思考怎樣做更省力。","action":"選一個容易堆積雜物的地方，建立十分鐘內能完成的整理方式。","quote":"「掃完又落葉，是樹在做樹的事，不是你掃得不夠虔誠。」"},"ja":{"name":"庭を掃く","originalName":"掃庭","grade":"中吉","poem":["朝、階の前の葉を掃き","風が吹けばまた庭に満ちる","毎日することを嫌わず","ゆっくり庭を清めてゆく"],"meaning":"整理は一度きりの成果ではなく、暮らしと続けて調整していくものです。片づけてもまた散らかるからといって、努力を否定しないでください。もっと楽に続ける方法を考えてもよいのです。","action":"物がたまりやすい場所を一つ選び、十分以内でできる片づけ方を決めましょう。","quote":"「掃いた後にまた葉が落ちるのは、木が木の仕事をしているからだ。あなたの掃き方が不敬なのではない。」","category":"家庭・住まい"},"en":{"name":"Sweeping the Courtyard","originalName":"掃庭","grade":"Moderately Favorable","poem":["At dawn, sweep the leaves from the steps;","The wind will fill the yard again.","Do not resent the daily work;","Little by little, the courtyard grows clear."],"meaning":"Organizing is not a one-time achievement; it is an ongoing adjustment to daily life. Do not dismiss your effort because things become messy again. You can also look for a way to make the task easier.","action":"Choose one place where clutter tends to gather and create a way to tidy it in ten minutes or less.","quote":"“Leaves fall again because trees are doing what trees do. It does not mean you swept without enough devotion.”","category":"Home & Family"}},{"id":52,"zh-Hant":{"id":52,"name":"舊案","grade":"平","category":"事業","poem":["案上重留字","燈前又見忙","若循前日法","怎止舊愁長"],"meaning":"同類型的工作問題反覆發生，可能需要檢查流程，而不是再靠個人加班補救。問題若藏在制度裡，只有努力很難改變結果。","action":"整理一項重複出錯的工作，提出一個能從源頭改善的做法。","quote":"「同一份文件改第八次，總該問問是不是需求根本沒定。」"},"ja":{"name":"古い案件","originalName":"舊案","grade":"平","poem":["机の上に同じ文字が残り","灯の下でまた忙しくなる","昨日と同じやり方を続ければ","古い悩みはいつまで続く"],"meaning":"同じ種類の仕事の問題が繰り返されるなら、個人の残業で補うのではなく、手順を見直す必要があるかもしれません。制度や仕組みに問題があるなら、努力だけで結果を変えるのは難しいものです。","action":"何度も間違いが起きる仕事を一つ整理し、原因から改善できる方法を提案しましょう。","quote":"「同じ書類を八回も直したのなら、そもそも要件が決まっているのか尋ねるべきだ。」","category":"仕事"},"en":{"name":"The Old Case","originalName":"舊案","grade":"Neutral","poem":["The same notes remain upon the desk;","Beneath the lamp, the work begins again.","If you keep using yesterday’s method,","How long will the old trouble last?"],"meaning":"When the same work problem keeps recurring, the process may need review rather than another round of personal overtime. If the cause lies in the system, individual effort alone may not change the outcome.","action":"Review one task where errors keep recurring and propose a change that addresses the source.","quote":"“If you have revised the same document eight times, perhaps it is time to ask whether the requirements were ever settled.”","category":"Career"}},{"id":53,"zh-Hant":{"id":53,"name":"橋成","grade":"中吉","category":"事業","poem":["雙岸同修橋","石木各分明","責任先題定","橋通路自平"],"meaning":"合作需要分清各自負責什麼、何時交付、遇到問題找誰。說清楚並非不信任，而是讓彼此有方法完成事情。","action":"替目前一項合作寫下明確的交付內容與負責人。","quote":"「橋不是靠『大家加油』就會自己長出來的。」"},"ja":{"name":"橋を架ける","originalName":"橋成","grade":"中吉","poem":["両岸でともに橋を修め","石と木の役目を分ける","責任を先に書き定めれば","橋も道もおのずと整う"],"meaning":"協力には、誰が何を担当し、いつまでに何を渡し、問題が起きたら誰に相談するかを明確にする必要があります。明文化するのは不信感からではなく、互いが仕事を完了できるようにするためです。","action":"進行中の協力関係を一つ選び、成果物と担当者を明確に書き出しましょう。","quote":"「橋は『みんな頑張ろう』という掛け声だけでは架からぬ。」","category":"仕事"},"en":{"name":"Building a Bridge","originalName":"橋成","grade":"Moderately Favorable","poem":["Both shores work to mend the bridge;","Stone and timber each have their place.","Define responsibilities before the work begins,","And the bridge and road will take shape."],"meaning":"Collaboration requires clarity about who is responsible for what, when each part is due, and whom to contact when a problem arises. Making things explicit is not a sign of distrust; it gives everyone a way to complete the work.","action":"Choose one current collaboration and clearly write down its deliverables and owners.","quote":"“A bridge does not build itself just because everyone says, ‘Let’s do our best.’”","category":"Career"}},{"id":54,"zh-Hant":{"id":54,"name":"開卷","grade":"吉","category":"事業","poem":["新卷臨窗展","晨光照墨香","機緣需有備","落筆見文章"],"meaning":"新職務或計畫值得探索，但機會仍需要準備與實際能力配合。先確認自己的優勢與欠缺，再決定是否投入。","action":"挑選一項近期機會，列出已具備和需要補強的條件。","quote":"「門開了是好事，資料帶齊再進去會更好。」"},"ja":{"name":"書を開く","originalName":"開卷","grade":"吉","poem":["新しい巻を窓辺に広げ","朝の光が墨の香を照らす","機会には備えが必要","筆を下ろして初めて文となる"],"meaning":"新しい役割や計画には探る価値がありますが、機会を生かすには準備と実際の能力が必要です。自分の強みと不足を確かめてから、取り組むかどうかを決めましょう。","action":"最近の機会を一つ選び、すでに備わっている条件と補う必要のある条件を書き出しましょう。","quote":"「門が開いたのはよいことだ。資料をそろえてから入れば、なおよい。」","category":"仕事"},"en":{"name":"Opening the Book","originalName":"開卷","grade":"Favorable","poem":["A new volume opens beside the window;","Morning light falls upon the scent of ink.","Opportunity asks that you be prepared;","Only when the brush touches down does a work begin."],"meaning":"A new role or project may be worth exploring, but making use of an opportunity requires preparation and practical ability. Review your strengths and gaps before deciding whether to commit.","action":"Choose one recent opportunity and list what you already have and what you still need to strengthen.","quote":"“It is good that the door has opened. It is even better to bring the right documents before walking in.”","category":"Career"}},{"id":55,"zh-Hant":{"id":55,"name":"逆風","grade":"待時","category":"事業","poem":["逆風難掛帆","江急浪聲繁","先整舟中物","待穩再出關"],"meaning":"環境明顯不利時，強行加速可能讓代價更高。暫緩並非放棄，而是重新確認資源、風險和適合的推進方式。","action":"停止一項沒有準備好就硬推的工作，先補上最關鍵的資訊。","quote":"「逆風還要全速開船，舵可沒答應跟你一起逞強。」"},"ja":{"name":"逆風","originalName":"逆風","grade":"時を待つ","poem":["逆風には帆を張りにくく","川は急ぎ波音は騒がしい","まず舟の中を整え","安定してから関を出よう"],"meaning":"環境が明らかに不利なとき、無理に速度を上げると代償が大きくなることがあります。いったん止めるのは諦めではありません。資源、リスク、進め方を改めて確認することです。","action":"準備不足のまま無理に進めている仕事を一つ止め、最も重要な情報を補いましょう。","quote":"「逆風の中で全速航行を求めても、舵まで一緒に無理をするとは限らぬ。」","category":"仕事"},"en":{"name":"Against the Wind","originalName":"逆風","grade":"Wait for the Right Time","poem":["A sail is hard to raise against the wind;","The river runs fast, the waves grow loud.","First put the boat in order;","Wait for steadier waters before setting out."],"meaning":"When conditions are clearly unfavorable, forcing a faster pace may increase the cost. Pausing is not giving up; it is a chance to review your resources, risks, and the best way to proceed.","action":"Pause one task you are pushing forward without enough preparation, and fill in the most important missing information.","quote":"“Demanding full speed against the wind does not mean the rudder has agreed to strain itself.”","category":"Career"}},{"id":56,"zh-Hant":{"id":56,"name":"對帳","grade":"平","category":"事業","poem":["夜深翻舊帳","數目漸分明","功勞須有據","不讓苦無名"],"meaning":"工作中的投入、責任和回報若不清楚，容易累積不公平與誤會。事實與紀錄能幫助你談判，不必只靠情緒證明辛苦。","action":"整理最近完成的一項成果，留下可具體描述的紀錄。","quote":"「辛苦不是不能講，只是拿得出紀錄會比較省口水。」"},"ja":{"name":"帳簿を照らす","originalName":"對帳","grade":"平","poem":["夜更けに古い帳簿を開き","数字は少しずつ明らかになる","功績には確かな記録が要る","苦労を名もないままにするな"],"meaning":"仕事における投入、責任、見返りが曖昧なままだと、不公平や誤解が積み重なりやすくなります。事実と記録は交渉を助けてくれます。苦労を感情だけで証明する必要はありません。","action":"最近完了した成果を一つ整理し、具体的に説明できる記録を残しましょう。","quote":"「苦労を語ってはいけないわけではない。記録があれば、話す言葉を少し節約できる。」","category":"仕事"},"en":{"name":"Balancing the Books","originalName":"對帳","grade":"Neutral","poem":["Late at night, the old ledger opens;","The figures slowly come into view.","Achievements need evidence;","Do not let your effort go unnamed."],"meaning":"When effort, responsibility, and reward at work remain unclear, unfairness and misunderstanding can accumulate. Facts and records can support a negotiation; you do not have to prove your hard work through emotion alone.","action":"Document one recent accomplishment in a way that can be described concretely.","quote":"“You are allowed to talk about how hard you worked. Having a record simply saves you some explaining.”","category":"Career"}},{"id":57,"zh-Hant":{"id":57,"name":"持衡","grade":"上吉","category":"事業","poem":["雙手持天秤","千鈞不可扛","能為非必做","留力照前方"],"meaning":"能力足夠的人容易被交付更多工作，但會做不等於應該全部接下。合理分配承擔，才能讓成果和生活長久。","action":"檢視本週工作，挑出一項可以拒絕、委派或重新協商的責任。","quote":"「貧道能搬桌子，不代表全觀的桌子都得我搬。」"},"ja":{"name":"均衡を保つ","originalName":"持衡","grade":"上吉","poem":["両手で天秤を支え","千鈞の重さまで担うな","できることが必ずしも義務ではない","先へ進む力を残しておけ"],"meaning":"能力のある人ほど、次々と仕事を任されがちです。しかし、できることと、すべて引き受けるべきことは違います。負担を適切に分けることで、成果も暮らしも長く保てます。","action":"今週の仕事を見直し、断る、委任する、または再交渉できる責任を一つ選びましょう。","quote":"「貧道は机を運べる。だからといって、観中の机を全部運ぶ役目ではない。」","category":"仕事"},"en":{"name":"Keeping the Balance","originalName":"持衡","grade":"Very Favorable","poem":["Hold the scales with both hands;","Do not carry every thousand-weight burden.","Being able to do something does not make it your duty;","Keep strength for the road ahead."],"meaning":"People who are capable often find more and more work placed on their shoulders. But being able to do something does not mean you should take on everything. A fair distribution of responsibility helps both your work and your life remain sustainable.","action":"Review this week’s workload and identify one responsibility you can decline, delegate, or renegotiate.","quote":"“I can carry a table. That does not make me responsible for moving every table in the temple.”","category":"Career"}},{"id":58,"zh-Hant":{"id":58,"name":"機聲","grade":"中吉","category":"事業","poem":["機聲連夜響","補漏到天明","若改源頭處","方教百事輕"],"meaning":"不斷修補同一種錯誤，常讓真正的問題持續存在。比起再多做一次救火，更值得花力氣改善系統和協作方式。","action":"選一個讓人反覆返工的流程，寫下可以減少重工的一個改動。","quote":"「能修 bug 當然很好，但不能把 bug 當公司福利。」"},"ja":{"name":"機械の音","originalName":"機聲","grade":"中吉","poem":["機械の音は夜通し続き","夜明けまで穴を塞ぐ","根元を改めることができれば","あらゆる仕事は軽くなる"],"meaning":"同じ不具合を何度も修正していると、本当の問題が残り続けることがあります。もう一度火消しをするより、仕組みや協力の方法を改善するほうに力を使う価値があります。","action":"何度も手戻りが起きる手順を一つ選び、やり直しを減らせる変更を一つ書き出しましょう。","quote":"「バグを直せるのは結構だ。だが、バグを福利厚生にしてはならぬ。」","category":"仕事"},"en":{"name":"The Sound of the Machine","originalName":"機聲","grade":"Moderately Favorable","poem":["The machine hums through the night;","Repairs continue until dawn.","If the source can finally be changed,","Every task will grow lighter."],"meaning":"Repeatedly patching the same error can leave the real problem untouched. Rather than putting out the same fire again, it may be more worthwhile to improve the system and the way people work together.","action":"Choose one process that repeatedly creates rework and write down one change that could reduce it.","quote":"“Fixing bugs is useful. Making bugs part of the employee benefits package is not.”","category":"Career"}},{"id":59,"zh-Hant":{"id":59,"name":"收支","grade":"平","category":"財務","poem":["錢入如流水","錢出似歸潮","若問庫中數","先將細帳抄"],"meaning":"收入看起來穩定，仍不代表手上有足夠可運用的資金。先掌握固定支出、負債與剩餘現金，再談下一步。","action":"記下這個月三項最大支出，確認有沒有不曾留意的固定費用。","quote":"「算財運之前，帳本先翻開。不然財神也得跟你要明細。」"},"ja":{"name":"収支","originalName":"收支","grade":"平","poem":["金は流れる水のように入り","潮が戻るように出てゆく","蔵の中の数を知りたいなら","まず細かな帳面をつけよ"],"meaning":"収入が安定して見えても、自由に使える資金が十分にあるとは限りません。次のことを考える前に、固定費、負債、手元に残る現金を把握しましょう。","action":"今月の大きな支出を三つ記録し、気づいていなかった定期費用がないか確認しましょう。","quote":"「財運を占う前に、まず帳簿を開きなさい。さもなくば財神にも明細を求められる。」","category":"金銭・財務"},"en":{"name":"Income and Outgo","originalName":"收支","grade":"Neutral","poem":["Money flows in like running water;","It flows out like a receding tide.","If you wish to know what remains in the storehouse,","First keep a careful ledger."],"meaning":"A steady-looking income does not necessarily mean you have enough money available to use. Before planning your next move, understand your fixed expenses, debts, and remaining cash.","action":"Record your three largest expenses this month and check for recurring costs you may have overlooked.","quote":"“Before asking about your fortune with money, open the ledger. Even the God of Wealth will ask for an itemized statement.”","category":"Finances"}},{"id":60,"zh-Hant":{"id":60,"name":"長耕","grade":"中吉","category":"財務","poem":["田畝勤翻土","禾苗逐歲生","不爭朝夕價","久守見收成"],"meaning":"財務累積多半依靠持續儲蓄、風險管理與合適的配置，而非一次押對方向。要記得投資也可能虧損，長期不代表沒有風險。","action":"重新檢查自己的儲蓄目標與能承受的風險。","quote":"「種田不能每天把苗拔起來看長多高，帳戶倒是可以少刷新幾次。」"},"ja":{"name":"長く耕す","originalName":"長耕","grade":"中吉","poem":["畑を丹念に耕し","苗は年ごとに育つ","朝夕の値を争わず","長く守れば実りが見える"],"meaning":"財産を築くには、継続的な貯蓄、リスク管理、適切な配分が役立つことが多く、一度の賭けに勝つことだけが道ではありません。投資には損失の可能性もあり、長期だからといってリスクがなくなるわけではありません。","action":"貯蓄の目標と、自分が受け入れられるリスクを改めて確認しましょう。","quote":"「苗の高さを確かめるために毎日引き抜いてはならぬ。口座の更新も少し減らすとよい。」","category":"金銭・財務"},"en":{"name":"Long Cultivation","originalName":"長耕","grade":"Moderately Favorable","poem":["The field is turned with care;","The seedlings grow year by year.","Do not chase every day’s price;","With patience, the harvest will appear."],"meaning":"Building financial stability often depends on steady saving, risk management, and suitable allocation—not on making one perfect bet. Investments can lose value, and a long horizon does not eliminate risk.","action":"Review your savings goals and the level of risk you can realistically tolerate.","quote":"“Do not pull up a seedling every day to see how tall it has grown. You might also refresh your account balance a little less often.”","category":"Finances"}},{"id":61,"zh-Hant":{"id":61,"name":"急潮","grade":"待時","category":"財務","poem":["浪起眾舟奔","岸邊人語喧","莫隨潮影逐","先看水深淺"],"meaning":"看見別人獲利或市場突然熱鬧，容易想立刻跟上。越是急迫的時候，越要確認資金用途、風險與退出條件。","action":"暫緩一筆衝動支出或投資，寫下自己真正理解的風險。","quote":"「人家喊上船，你至少先問這船有沒有救生衣。」"},"ja":{"name":"急な潮","originalName":"急潮","grade":"時を待つ","poem":["波が立てば舟は一斉に走り","岸辺の声は騒がしくなる","潮の影を追いかけず","まず水の深さを見よ"],"meaning":"他人の利益や市場の急な盛り上がりを見ると、すぐに追いつきたくなるものです。急かされるときほど、資金の用途、リスク、撤退条件を確かめてください。","action":"衝動的な支出や投資を一つ保留し、自分が本当に理解しているリスクを書き出しましょう。","quote":"「皆が船に乗れと叫ぶなら、せめて救命胴衣があるか尋ねなさい。」","category":"金銭・財務"},"en":{"name":"The Sudden Tide","originalName":"急潮","grade":"Wait for the Right Time","poem":["When waves rise, every boat rushes out;","Voices grow loud along the shore.","Do not chase the tide’s reflection;","First find out how deep the water is."],"meaning":"Seeing others profit or a market suddenly surge can make you want to jump in at once. The more urgent it feels, the more important it is to check the purpose of the funds, the risks, and your exit conditions.","action":"Pause one impulsive purchase or investment and write down the risks you genuinely understand.","quote":"“If everyone is shouting for you to get on board, at least ask whether the boat has life jackets.”","category":"Finances"}},{"id":62,"zh-Hant":{"id":62,"name":"分泉","grade":"吉","category":"財務","poem":["山泉分數道","澆灌各畦田","莫使一渠斷","滿園皆待憐"],"meaning":"將資源全部綁在單一來源，可能承擔過高風險。規劃不同用途與緩衝，可以減少突發變化對生活的衝擊。","action":"區分日常支出、緊急預備與長期目標的資金用途。","quote":"「一條水管顧全院，水管一破就全員排隊。」"},"ja":{"name":"泉を分ける","originalName":"分泉","grade":"吉","poem":["山の泉は幾筋にも分かれ","畑の畝をそれぞれ潤す","水路を一つだけに頼らず","庭全体を枯らさぬように"],"meaning":"資源を一つの収入源や用途だけに結びつけると、リスクが高くなることがあります。用途を分け、余裕を持たせることで、突然の変化が暮らしに与える影響を減らせます。","action":"日常の支出、緊急時の備え、長期目標のための資金を分けて考えましょう。","quote":"「庭じゅうを一本の水管で養えば、その管が壊れたとき皆が列を作ることになる。」","category":"金銭・財務"},"en":{"name":"Dividing the Spring","originalName":"分泉","grade":"Favorable","poem":["The mountain spring divides into many streams;","Each waters a different field.","Do not let one channel be your only source;","Keep the whole garden from going dry."],"meaning":"Tying all your resources to a single source or purpose can create excessive risk. Separating funds by purpose and keeping a buffer can reduce the impact of sudden changes on daily life.","action":"Separate the money intended for everyday expenses, emergencies, and long-term goals.","quote":"“If one pipe waters the whole garden, everyone will be queuing when that pipe breaks.”","category":"Finances"}},{"id":63,"zh-Hant":{"id":63,"name":"修屋","grade":"平","category":"財務","poem":["新瓦未防雨","舊牆偶裂痕","日常留一備","風至可安門"],"meaning":"生活裡總有設備故障或意料之外的開銷。把風險當成需要預留空間的現實，比祈求永遠沒有意外更踏實。","action":"估算一筆常見的突發費用，檢查目前是否有應急準備。","quote":"「屋頂不會先寄通知說下週要漏水，錢最好先備著。」"},"ja":{"name":"屋根を直す","originalName":"修屋","grade":"平","poem":["新しい瓦も雨を防ぎきれず","古い壁には時折ひびが入る","日々の備えを少し残せば","風が来ても戸を守れる"],"meaning":"暮らしには設備の故障や予想外の出費がつきものです。何も起こらないよう祈るより、リスクに備える余地を残しておくほうが現実的です。","action":"よくある突発的な出費を一つ見積もり、今そのための備えがあるか確認しましょう。","quote":"「屋根は来週雨漏りすると予告状を送ってこぬ。だからこそ、金は先に備えておくのだ。」","category":"金銭・財務"},"en":{"name":"Mending the House","originalName":"修屋","grade":"Neutral","poem":["Even new tiles cannot stop every rain;","An old wall may crack from time to time.","Keep a little in reserve each day,","And you can secure the door when the wind comes."],"meaning":"Appliances break and unexpected expenses arise. It is more practical to leave room for such risks than to hope nothing will ever go wrong.","action":"Estimate one common unexpected expense and check whether you are prepared to cover it.","quote":"“A roof will not send you a notice saying it plans to leak next week. That is why you prepare the money in advance.”","category":"Finances"}},{"id":64,"zh-Hant":{"id":64,"name":"取捨","grade":"中吉","category":"財務","poem":["囊中唯數兩","市上百般珍","先買當需物","餘香待後春"],"meaning":"有限的資源必須分配，並不代表你不配擁有喜歡的東西。只是先後順序不同，能讓選擇少一些壓力。","action":"把近期想買的東西分成必要、想要與可以延後三類。","quote":"「喜歡的都買也不是不行，前提是下個月還有飯吃。」"},"ja":{"name":"取捨選択","originalName":"取捨","grade":"中吉","poem":["袋の中にはわずかな銭","市には数えきれぬ宝","まず今必要なものを買い","残りの楽しみは次の春へ"],"meaning":"限られた資源を配分する必要があっても、好きなものを持つ資格がないという意味ではありません。順番を決めることで、選択に伴う負担を軽くできます。","action":"近いうちに買いたいものを「必要」「欲しい」「後回しにできる」の三つに分けましょう。","quote":"「好きなものを全部買うのもよい。来月の食事代が残るなら、の話だが。」","category":"金銭・財務"},"en":{"name":"Choosing What to Keep","originalName":"取捨","grade":"Moderately Favorable","poem":["There are only a few coins in the pouch;","The market is full of countless treasures.","Buy first what you need now;","Let the other pleasures wait for spring."],"meaning":"Having to allocate limited resources does not mean you do not deserve the things you enjoy. Setting priorities can make your choices less stressful.","action":"Sort the things you want to buy soon into three groups: necessary, desired, and safe to postpone.","quote":"“There is nothing wrong with buying everything you like—provided you still have money for food next month.”","category":"Finances"}},{"id":65,"zh-Hant":{"id":65,"name":"藏金","grade":"平","category":"財務","poem":["帳上金山在","開箱未見銀","若逢臨急事","可用有幾分"],"meaning":"資產價值與眼前能動用的現金不是同一件事。安排財務時，要留意流動性、期限和實際支出需求。","action":"確認一項資產是否能在需要時安全、及時地轉為可用資金。","quote":"「帳面有錢很好，但冰箱壞了不會接受股票當修理費。」"},"ja":{"name":"隠された金","originalName":"藏金","grade":"平","poem":["帳面には金山がある","箱を開けても銀は見えぬ","急な用事が起きたとき","いったい幾分使えるだろう"],"meaning":"資産の価値と、今すぐ使える現金は同じではありません。財務を整えるときは、流動性、期限、実際の支出予定に注意しましょう。","action":"必要なときに安全かつ速やかに現金化できる資産かどうか、一つ確認しましょう。","quote":"「帳面に金があるのは結構だ。だが、壊れた冷蔵庫は修理代に株を受け取ってはくれぬ。」","category":"金銭・財務"},"en":{"name":"Hidden Gold","originalName":"藏金","grade":"Neutral","poem":["A mountain of gold stands in the ledger;","Open the chest, and no silver appears.","When an urgent need arrives,","How much can you truly put to use?"],"meaning":"The value of your assets and the cash you can use right now are not the same thing. When planning your finances, pay attention to liquidity, timing, and actual spending needs.","action":"Check whether one of your assets can be converted into usable cash safely and in time when needed.","quote":"“It is nice to have money on paper. But a broken refrigerator will not accept stocks as payment for repairs.”","category":"Finances"}},{"id":66,"zh-Hant":{"id":66,"name":"對價","grade":"吉","category":"財務","poem":["錦盒光如晝","簽章字若針","先知交換物","才識此中金"],"meaning":"看似優厚的交易，可能藏著限制、成本或對方希望你承擔的責任。看懂交換條件，才有可能分辨真正的利益。","action":"重新檢查一份合約、會員方案或交易條款中的附帶費用。","quote":"「禮盒包得漂亮，裡面要付什麼帳還是得拆開看。」"},"ja":{"name":"交換の価値","originalName":"對價","grade":"吉","poem":["錦の箱は昼のように輝き","署名の文字は針のように細い","何を交換するのか先に知り","その価値を見極めよ"],"meaning":"一見有利な取引にも、制限や費用、相手が負担させたい責任が隠れていることがあります。交換条件を理解して初めて、本当の利益を見分けられます。","action":"契約、会員プラン、取引条件の付帯費用を改めて確認しましょう。","quote":"「贈り物の箱が美しくても、中にどんな請求が入っているかは開けてみねば分からぬ。」","category":"金銭・財務"},"en":{"name":"The Price of Exchange","originalName":"對價","grade":"Favorable","poem":["The brocade box shines like daylight;","The signature is fine as a needle.","Know what you are giving in exchange;","Only then can you see its true worth."],"meaning":"An offer that looks generous may conceal restrictions, costs, or responsibilities the other party expects you to take on. Only by understanding the terms of exchange can you judge its real value.","action":"Review the additional fees and conditions attached to a contract, membership plan, or transaction.","quote":"“A gift box may be beautifully wrapped. You still have to open it to see what bill is inside.”","category":"Finances"}},{"id":67,"zh-Hant":{"id":67,"name":"守庫","grade":"上吉","category":"財務","poem":["倉門常細檢","雨至早修牆","手握三分備","方能守歲長"],"meaning":"財務穩定更多來自持續檢查與合理防備，而不是一次運氣。保留彈性、避免過度承諾，能讓未來有更多選擇。","action":"安排一次固定的財務檢視，包含支出、準備金與風險。","quote":"「守得住的才算自己的。貧道說的是規劃，不是叫你抱著錢箱睡。」"},"ja":{"name":"蔵を守る","originalName":"守庫","grade":"上吉","poem":["蔵の門をいつも細かく点検し","雨が来る前に壁を直す","三分の備えを手にしてこそ","長い歳月を守ってゆける"],"meaning":"財務の安定は、一度の幸運よりも、継続的な確認と妥当な備えから生まれます。柔軟性を残し、過度な約束を避ければ、将来の選択肢を増やせます。","action":"支出、予備資金、リスクを含めた定期的な家計チェックを一度予定しましょう。","quote":"「守りきれるものこそ自分のものだ。貧道が言うのは計画のこと。金箱を抱いて寝ろという意味ではない。」","category":"金銭・財務"},"en":{"name":"Guarding the Storehouse","originalName":"守庫","grade":"Very Favorable","poem":["Inspect the storehouse gate with care;","Repair the wall before the rain arrives.","Keep a measure of reserve at hand,","And you can protect what lasts through the years."],"meaning":"Financial stability comes more from regular reviews and sensible preparation than from a single stroke of luck. Preserve flexibility and avoid overcommitting, and you will have more choices in the future.","action":"Schedule a regular financial review that covers spending, reserves, and risk.","quote":"“What you can protect is what remains yours. I speak of planning, not sleeping with your arms around a cash box.”","category":"Finances"}},{"id":68,"zh-Hant":{"id":68,"name":"問字","grade":"吉","category":"學業／進修","poem":["初讀多生字","翻書問舊師","不知非可恥","敢問始能知"],"meaning":"遇到不懂的內容，願意提問是學習真正開始的地方。別因怕看起來不夠厲害，就錯過弄清楚問題的機會。","action":"針對最近的一個疑惑，找一份可靠資料或請教適合的人。","quote":"「看不懂就問，經書又不會因為你問一句就生氣。」"},"ja":{"name":"字を問う","originalName":"問字","grade":"吉","poem":["初めて読む字は多く","古い師に書を開いて尋ねる","知らぬことは恥ではない","問う勇気から知は始まる"],"meaning":"分からない内容に出会ったとき、質問する意思こそ学びの始まりです。賢く見られたいという気持ちから、疑問を解く機会を逃さないでください。","action":"最近の疑問を一つ選び、信頼できる資料を探すか、適切な人に尋ねましょう。","quote":"「分からなければ尋ねればよい。経典は質問を一つされたくらいで怒りはせぬ。」","category":"学業・学び"},"en":{"name":"Asking About a Word","originalName":"問字","grade":"Favorable","poem":["A first reading brings many unfamiliar words;","Open the book and ask an old teacher.","Not knowing is no shame;","Knowledge begins with the courage to ask."],"meaning":"When you encounter something you do not understand, being willing to ask is where learning begins. Do not miss the chance to clarify a question just because you fear looking less capable.","action":"Choose one recent question and look for a reliable source or ask someone qualified to help.","quote":"“If you do not understand, ask. The scriptures will not get angry over one question.”","category":"Study & Learning"}},{"id":69,"zh-Hant":{"id":69,"name":"刻舟","grade":"平","category":"學業／進修","poem":["舊舟留刻痕","江水已東奔","昔日量深尺","如今未必存"],"meaning":"過去有用的知識與方法，遇到新的條件不一定仍然適合。保持更新與驗證，才能讓經驗真正成為助力。","action":"檢查一個自己習以為常的做法，看看它現在是否還適用。","quote":"「船走了還盯著刻痕，魚都快笑你了。」"},"ja":{"name":"舟に刻む","originalName":"刻舟","grade":"平","poem":["古い舟に刻んだ跡が残る","川の水はすでに東へ流れた","昔の深さを測った印は","今も役立つとは限らない"],"meaning":"以前は役に立った知識や方法も、新しい条件のもとでは適さないことがあります。更新し、確かめ続けることで、経験は本当の助けになります。","action":"当たり前だと思って続けている方法を一つ選び、今も適切かどうか確かめましょう。","quote":"「舟が進んだのに刻み跡ばかり見ていては、魚に笑われてしまう。」","category":"学業・学び"},"en":{"name":"Marking the Boat","originalName":"刻舟","grade":"Neutral","poem":["The old boat still bears its carved mark;","The river has already flowed east.","The mark that measured yesterday’s depth","May no longer serve today."],"meaning":"Knowledge and methods that once worked may no longer fit new conditions. Keep updating and testing them so that experience remains useful.","action":"Choose one familiar method you use without thinking and check whether it still fits the situation.","quote":"“If you keep staring at the mark after the boat has moved on, even the fish may laugh at you.”","category":"Study & Learning"}},{"id":70,"zh-Hant":{"id":70,"name":"夜讀","grade":"待時","category":"學業／進修","poem":["夜半燈猶亮","書聲到五更","合卷先安睡","明朝眼更明"],"meaning":"熬夜不一定代表學得更扎實，長期疲勞還可能影響理解與記憶。遇到效率下降時，先休息再重新安排進度。","action":"替今天的學習訂一個合理的停止時間。","quote":"「把書讀到天亮，跟把內容讀進腦袋，是兩個 KPI。」"},"ja":{"name":"夜の読書","originalName":"夜讀","grade":"時を待つ","poem":["夜半を過ぎても灯は明るく","読書の声は五更まで続く","本を閉じてまず眠りなさい","明日の目はもっと澄む"],"meaning":"夜更かしをすれば必ず深く学べるわけではありません。疲労が続けば理解や記憶にも影響します。効率が落ちてきたら、まず休み、進め方を改めて整えましょう。","action":"今日の学習を終える、無理のない時刻を決めましょう。","quote":"「本を夜明けまで読むことと、内容を頭に入れることは、別々のKPIだ。」","category":"学業・学び"},"en":{"name":"Reading at Night","originalName":"夜讀","grade":"Wait for the Right Time","poem":["The lamp still burns past midnight;","The pages turn until the fifth watch.","Close the book and sleep first;","Tomorrow your eyes will be clearer."],"meaning":"Staying up late does not necessarily mean you are learning more deeply. Ongoing fatigue can affect understanding and memory. When your efficiency drops, rest first and then reorganize your study plan.","action":"Set a reasonable time to stop studying today.","quote":"“Reading until dawn and getting the material into your head are two different KPIs.”","category":"Study & Learning"}},{"id":71,"zh-Hant":{"id":71,"name":"藏書","grade":"中吉","category":"學業／進修","poem":["萬卷藏高閣","翻時方有功","連章成一脈","知識始相通"],"meaning":"收集資料不等於已經理解。把知識整理成可找到、可運用的結構，才能在真正需要時派上用場。","action":"選一份收藏很久的資料，寫出三句自己的理解。","quote":"「書買回來很有氣氛，會自己翻頁的目前還沒見過。」"},"ja":{"name":"書を蔵す","originalName":"藏書","grade":"中吉","poem":["幾万巻もの書を高殿に蔵し","開いて初めて功を成す","章をつなげて一つの流れとし","知識はそこで通じ合う"],"meaning":"資料を集めることと、理解することは同じではありません。知識を探しやすく、使いやすい形に整理してこそ、必要なときに役立ちます。","action":"長く保存している資料を一つ選び、自分の理解を三つの文にまとめましょう。","quote":"「本を買い並べれば雰囲気は出る。自分でページをめくる本は、まだ見たことがない。」","category":"学業・学び"},"en":{"name":"The Book Collection","originalName":"藏書","grade":"Moderately Favorable","poem":["A thousand volumes rest in the high pavilion;","Their value appears when they are opened.","Link the chapters into one current,","And knowledge begins to connect."],"meaning":"Collecting information is not the same as understanding it. Organize knowledge so it can be found and applied when it is needed.","action":"Choose one resource you have saved for a long time and summarize your understanding in three sentences.","quote":"“Buying books creates a certain atmosphere. I have yet to see one turn its own pages.”","category":"Study & Learning"}},{"id":72,"zh-Hant":{"id":72,"name":"試筆","grade":"吉","category":"學業／進修","poem":["新墨沾衣袖","初書字未勻","重描三五遍","筆下漸成文"],"meaning":"從不熟練到掌握，需要允許自己出錯並實際修正。每次練習得到的回饋，比只想像完美成果更有幫助。","action":"完成一個可以立即測試的小作品，記下下一次要改的地方。","quote":"「第一筆寫歪了就把筆折斷，文房四寶會很辛苦。」"},"ja":{"name":"筆を試す","originalName":"試筆","grade":"吉","poem":["新しい墨が袖に触れ","初めの字はまだ整わない","三度五度と描き直せば","筆先に少しずつ文が宿る"],"meaning":"不慣れな状態から身につけるには、失敗を許し、実際に修正する必要があります。完璧な成果を想像するだけより、練習のたびに得られる反応のほうが役に立ちます。","action":"すぐに試せる小さな作品を一つ完成させ、次に直したい点を記録しましょう。","quote":"「最初の一筆が曲がったからと筆を折っては、筆記具一式が気の毒だ。」","category":"学業・学び"},"en":{"name":"Trying the Brush","originalName":"試筆","grade":"Favorable","poem":["Fresh ink stains the sleeve;","The first characters are uneven.","Trace them again, three or five times,","And a poem slowly forms beneath the brush."],"meaning":"Moving from unfamiliarity to skill requires allowing mistakes and correcting them in practice. Feedback from each attempt is more useful than merely imagining a perfect result.","action":"Complete one small piece of work that can be tested right away, and note what you want to improve next time.","quote":"“If you break the brush because the first stroke went crooked, you will have to apologize to the entire writing set.”","category":"Study & Learning"}},{"id":73,"zh-Hant":{"id":73,"name":"辨經","grade":"平","category":"學業／進修","poem":["故卷千家注","同文百樣聲","欲尋原本意","先辨據何憑"],"meaning":"同一份內容可能有不同解釋，但不是所有說法都有相同的證據。辨認來源、事實和推論，有助於避免被流暢的說詞帶走。","action":"找出一個常聽見的說法，確認它最初出自哪份資料。","quote":"「能講得頭頭是道是一回事，出處還是要找。」"},"ja":{"name":"経を見分ける","originalName":"辨經","grade":"平","poem":["古い巻には多くの注釈","同じ文にも百の声がある","元の意味を探すなら","何を根拠に語るか見分けよ"],"meaning":"同じ内容にも複数の解釈がありますが、すべての主張に同じだけの根拠があるわけではありません。出典、事実、推論を見分ければ、流暢な言葉に引きずられにくくなります。","action":"よく耳にする主張を一つ選び、それが最初にどの資料から出たのか確かめましょう。","quote":"「筋道立てて話せることと、出典を示せることは別だ。出どころは確かめねばならぬ。」","category":"学業・学び"},"en":{"name":"Discerning the Text","originalName":"辨經","grade":"Neutral","poem":["An old text bears many commentaries;","One passage speaks in a hundred voices.","If you seek the meaning at its source,","First ask what evidence each claim rests upon."],"meaning":"The same material can be interpreted in different ways, but not every interpretation has equal evidence behind it. Distinguishing sources, facts, and inferences helps you avoid being carried away by fluent words.","action":"Choose a claim you often hear and check which source it originally came from.","quote":"“Speaking convincingly and showing your sources are two different things. The origin still needs to be checked.”","category":"Study & Learning"}},{"id":74,"zh-Hant":{"id":74,"name":"登階","grade":"上吉","category":"學業／進修","poem":["石階層層上","回頭百級長","今朝推遠戶","前路又晨光"],"meaning":"長期累積已經讓你有能力嘗試更進一步的挑戰。新的階段仍有陌生事物，但不必因此否定自己走過的路。","action":"挑選一項稍高於現有能力的挑戰，訂下第一個可以完成的步驟。","quote":"「你都爬到這層了，別因為下一層還有樓梯就說白爬。」"},"ja":{"name":"階を上る","originalName":"登階","grade":"上吉","poem":["石段は幾重にも続き","振り返れば百段を越えた","今朝、遠くの扉を押せば","その先にもまた朝の光"],"meaning":"長く積み重ねてきたものが、次の挑戦に手を伸ばす力になっています。新しい段階には知らないこともありますが、それを理由に今までの歩みを否定する必要はありません。","action":"今の力より少し高い挑戦を一つ選び、最初に達成できる手順を決めましょう。","quote":"「ここまで登ってきたのに、次にも階段があるからといって、登ったことまで無駄にしてはならぬ。」","category":"学業・学び"},"en":{"name":"Climbing the Steps","originalName":"登階","grade":"Very Favorable","poem":["Stone steps rise one after another;","Look back—you have climbed a hundred.","Push open the distant door today,","And another morning waits beyond."],"meaning":"What you have built over time has given you the ability to attempt a greater challenge. The next stage will contain unfamiliar things, but that is no reason to dismiss the road you have already traveled.","action":"Choose one challenge slightly beyond your current ability and define the first achievable step.","quote":"“You have climbed this far. Do not call the climb wasted just because there are more steps ahead.”","category":"Study & Learning"}},{"id":75,"zh-Hant":{"id":75,"name":"息肩","grade":"平","category":"健康／身心","poem":["肩上挑沉擔","行久步難輕","放下歇片刻","再量路幾程"],"meaning":"疲累不是意志不夠堅定的證明，可能只是身體與生活負荷正在提醒你需要調整。先確保休息，再評估接下來能承擔多少。","action":"今天安排一段不被工作或訊息打斷的休息時間。","quote":"「擔子先放地上，它不會因為你歇一會兒就告狀。」"},"ja":{"name":"肩を休める","originalName":"息肩","grade":"平","poem":["肩には重い荷を担ぎ","歩み続ければ足も重くなる","荷を下ろしてしばし休み","残る道の長さを測ろう"],"meaning":"疲れは、意志が弱い証拠ではありません。身体や暮らしの負荷が、調整を求めているのかもしれません。まず休息を確保し、その後でどれだけ引き受けられるかを考えましょう。","action":"今日は仕事やメッセージに邪魔されない休息の時間を確保しましょう。","quote":"「荷物を地面に置いても、荷物があなたを告げ口するわけではない。」","category":"健康・心身"},"en":{"name":"Resting Your Shoulders","originalName":"息肩","grade":"Neutral","poem":["A heavy load rests upon your shoulders;","The longer you walk, the heavier your steps.","Set the burden down and rest a while;","Then measure how much road remains."],"meaning":"Fatigue is not proof of weak will. Your body or daily life may be telling you that something needs to change. Secure time to rest first, then consider how much more you can reasonably take on.","action":"Set aside a period of rest today when work and messages cannot interrupt you.","quote":"“Set the burden on the ground. It will not report you for taking a break.”","category":"Health & Well-being"}},{"id":76,"zh-Hant":{"id":76,"name":"晨息","grade":"中吉","category":"健康／身心","poem":["日出開簾影","茶溫醒午眠","作息隨身調","平穩勝求全"],"meaning":"適合自己的生活節奏，不必完全照著別人的時間表。與其要求立刻完美，不如觀察哪些習慣能讓自己穩定一些。","action":"選一項睡前或起床後的小習慣，連續幾天觀察效果。","quote":"「把作息排得像軍營，未必就睡得像嬰兒。」"},"ja":{"name":"朝のひと息","originalName":"晨息","grade":"中吉","poem":["日の出とともに簾を開け","温かな茶が昼寝の目を覚ます","暮らしの時刻は自分に合わせ","完璧より穏やかさを選ぼう"],"meaning":"自分に合う生活のリズムは、他人の時間割に完全に合わせる必要はありません。すぐに完璧を目指すより、どの習慣が自分を安定させるか観察しましょう。","action":"寝る前か起きた後の小さな習慣を一つ選び、数日続けて効果を観察しましょう。","quote":"「生活を軍隊のように整えたからといって、赤子のように眠れるとは限らぬ。」","category":"健康・心身"},"en":{"name":"A Morning’s Pause","originalName":"晨息","grade":"Moderately Favorable","poem":["At sunrise, open the curtain;","Warm tea wakes the afternoon sleeper.","Adjust your routine to your own needs;","Steadiness is better than perfection."],"meaning":"A rhythm that suits you does not have to match someone else’s timetable. Rather than demanding perfection at once, notice which habits help you feel steadier.","action":"Choose one small habit before bed or after waking, and observe its effect over several days.","quote":"“A military-grade schedule does not guarantee that you will sleep like a baby.”","category":"Health & Well-being"}},{"id":77,"zh-Hant":{"id":77,"name":"慢茶","grade":"待時","category":"健康／身心","poem":["茶葉沉杯底","水溫慢慢勻","傷疲無定刻","養息莫催春"],"meaning":"復原與調整都可能需要時間，不能用一個標準期限要求自己。若有持續不適，也應尋求合適專業協助，不靠籤象判斷原因。","action":"先確認目前最需要的休養條件，必要時安排專業評估。","quote":"「茶還燙就急著喝，燙到的還是自己的舌頭。」"},"ja":{"name":"ゆっくりと茶を","originalName":"慢茶","grade":"時を待つ","poem":["茶葉は杯の底に沈み","湯の温度はゆっくり整う","傷や疲れに決まった時はない","春を急かさず息を養え"],"meaning":"回復や調整には時間がかかることがあり、決まった期限で自分を測る必要はありません。不調が続く場合は、籤の象意で原因を判断せず、適切な専門家に相談してください。","action":"今もっとも必要な休養の条件を確認し、必要なら専門家による評価を手配しましょう。","quote":"「茶がまだ熱いのに急いで飲めば、舌をやけどするのは自分だ。」","category":"健康・心身"},"en":{"name":"Tea, Slowly","originalName":"慢茶","grade":"Wait for the Right Time","poem":["Tea leaves settle at the bottom of the cup;","The water finds its warmth slowly.","There is no fixed hour for healing or fatigue;","Do not hurry spring—nourish your breath."],"meaning":"Recovery and adjustment can take time; you do not have to measure yourself against a fixed deadline. If discomfort persists, seek appropriate professional advice rather than using a fortune to determine its cause.","action":"Identify the conditions you most need for rest, and arrange a professional assessment if appropriate.","quote":"“If you rush to drink tea while it is still hot, your own tongue will be the one that gets burned.”","category":"Health & Well-being"}},{"id":78,"zh-Hant":{"id":78,"name":"開窗","grade":"吉","category":"健康／身心","poem":["閉室塵微積","推窗見樹青","清風來有路","心緒漸分明"],"meaning":"當生活被資訊與壓力塞滿，適度改變環境有時能帶來喘息。這不是要求你靠意志消除不舒服，而是為自己多留一點空間。","action":"找一個舒適安靜的角落，暫時離開讓自己緊繃的刺激。","quote":"「窗不是非得全開，有風進來又不著涼才是本事。」"},"ja":{"name":"窓を開く","originalName":"開窗","grade":"吉","poem":["閉じた部屋には塵が積もり","窓を押せば青い木が見える","清らかな風にも通り道があり","心のもやも少しずつ晴れる"],"meaning":"情報やプレッシャーで暮らしがいっぱいになったとき、環境を少し変えることで息がつける場合があります。不快感を意志の力だけで消す必要はありません。自分のための余白を増やしましょう。","action":"心地よく静かな場所を見つけ、緊張を生む刺激からしばらく離れましょう。","quote":"「窓は必ずしも全開にせずともよい。風を入れて、冷えないようにするのが腕前だ。」","category":"健康・心身"},"en":{"name":"Opening the Window","originalName":"開窗","grade":"Favorable","poem":["Dust gathers in a closed room;","Open the window, and green trees appear.","Even a fresh breeze needs a passage;","The mind’s haze may slowly clear."],"meaning":"When life is crowded with information and pressure, a small change of surroundings can offer breathing room. You do not have to will discomfort away. Make a little more space for yourself.","action":"Find a comfortable, quiet place and step away for a while from whatever is making you tense.","quote":"“A window need not be thrown wide open. The skill is letting in a breeze without catching a chill.”","category":"Health & Well-being"}},{"id":79,"zh-Hant":{"id":79,"name":"求援","grade":"上吉","category":"健康／身心","poem":["獨行山徑險","借杖未傷尊","問路逢良伴","平安可再奔"],"meaning":"求助不會降低你的能力或尊嚴。遇到超出自己能處理的身心問題，讓適合的人加入，能減少獨自承擔的負荷。","action":"列出一位可以聯繫的人或專業資源，為需要時做好準備。","quote":"「手上有傷還硬搬石頭，不會讓山神多發一張獎狀。」"},"ja":{"name":"助けを求める","originalName":"求援","grade":"上吉","poem":["一人で行く山道は険しく","杖を借りても尊厳は傷つかない","道を尋ねれば良き伴があり","また安心して歩き出せる"],"meaning":"助けを求めても、能力や尊厳が損なわれるわけではありません。自分だけでは対処しきれない心身の問題に直面したら、適切な人に加わってもらうことで、一人で背負う負担を減らせます。","action":"必要なときに連絡できる人、または専門的な支援先を一つ書き出しておきましょう。","quote":"「手に傷があるのに石を運び続けても、山の神が賞状をくれるわけではない。」","category":"健康・心身"},"en":{"name":"Asking for Help","originalName":"求援","grade":"Very Favorable","poem":["The mountain path is steep when walked alone;","Borrowing a staff does not diminish your dignity.","Ask the way and you may find a good companion;","Then you can travel safely once more."],"meaning":"Asking for help does not diminish your ability or dignity. When a physical or emotional difficulty exceeds what you can manage alone, bringing in the right person can reduce the burden you carry.","action":"Write down one person or professional resource you could contact if you need support.","quote":"“If you keep carrying stones with an injured hand, the mountain god will not award you a certificate.”","category":"Health & Well-being"}},{"id":80,"zh-Hant":{"id":80,"name":"知疲","grade":"平","category":"健康／身心","poem":["暮色侵書案","肩沉筆未停","莫嫌身已倦","先辨累何生"],"meaning":"休息後仍舊疲憊，可能與作息、壓力、身體狀態或環境有關，不能只用懶惰解釋。辨認狀況，才能決定需要改變什麼。","action":"記錄近期疲累出現的時間與情境；若持續或加重，考慮就醫。","quote":"「你可以嫌工作煩，但先別連身體提出的抗議都當雜音。」"},"ja":{"name":"疲れを知る","originalName":"知疲","grade":"平","poem":["夕暮れが書斎を覆い","肩は重く筆は止まらない","疲れた自分を責めず","何が疲れを生んだか見極めよ"],"meaning":"休んでも疲れが残るなら、生活リズム、ストレス、身体の状態、環境などが関係している可能性があります。怠けていると決めつけず、状況を見分けてから必要な変化を考えましょう。","action":"疲れが出る時間や状況を記録しましょう。長引いたり悪化したりする場合は、医療機関への相談を検討してください。","quote":"「仕事にうんざりするのはよい。だが、身体の抗議まで雑音として扱わぬことだ。」","category":"健康・心身"},"en":{"name":"Knowing Your Fatigue","originalName":"知疲","grade":"Neutral","poem":["Dusk settles over the writing desk;","The shoulders grow heavy, yet the brush keeps moving.","Do not blame yourself for being tired;","First learn what is causing the fatigue."],"meaning":"If fatigue remains even after rest, it may be related to routine, stress, physical condition, or your environment. Do not label yourself lazy; understand the situation before deciding what needs to change.","action":"Keep a record of when and where the fatigue occurs. If it persists or worsens, consider consulting a healthcare professional.","quote":"“You may be fed up with work. Just do not dismiss your body’s protests as background noise.”","category":"Health & Well-being"}},{"id":81,"zh-Hant":{"id":81,"name":"少聲","grade":"中吉","category":"健康／身心","poem":["市語連簷響","心頭百事喧","掩門留半刻","聽見自家言"],"meaning":"外界聲音與期待太多時，自己的需要容易被淹沒。暫時減少刺激，不等於逃避世界，而是騰出時間重新整理思緒。","action":"把手機通知關閉片刻，留一段不需回應任何人的時間。","quote":"「外面每個人都想講話，總得讓自己的耳朵排個休息日。」"},"ja":{"name":"静けさを選ぶ","originalName":"少聲","grade":"中吉","poem":["軒先まで街の声が響き","心には数えきれぬことが騒ぐ","門を閉じて半刻を残せば","自分自身の声が聞こえてくる"],"meaning":"外の声や期待が多すぎると、自分の必要が埋もれやすくなります。刺激を一時的に減らすことは世界から逃げることではなく、考えを整理する時間をつくることです。","action":"スマートフォンの通知をしばらく切り、誰にも返事をしなくてよい時間をつくりましょう。","quote":"「外の誰もが話したがっている。自分の耳にも休みの日を与えねばならぬ。」","category":"健康・心身"},"en":{"name":"Choosing Quiet","originalName":"少聲","grade":"Moderately Favorable","poem":["The city’s voices reach the eaves;","A hundred concerns clamor in the heart.","Close the gate and keep half an hour;","You may hear your own voice again."],"meaning":"When outside voices and expectations grow too loud, your own needs can disappear beneath them. Temporarily reducing stimulation is not escaping the world; it is making room to sort out your thoughts.","action":"Turn off your phone notifications for a while and make time when you do not have to respond to anyone.","quote":"“Everyone outside wants to speak. Your own ears deserve a day off, too.”","category":"Health & Well-being"}},{"id":82,"zh-Hant":{"id":82,"name":"渡口","grade":"平","category":"抉擇","poem":["渡口船雙列","南北各成航","欲問何舟好","先量所載囊"],"meaning":"兩條路沒有絕對優劣，各自對時間、資源與風險的要求不同。先確認自己帶得動什麼，再判斷哪種代價值得承擔。","action":"把兩個選項各自需要付出的成本寫成清單。","quote":"「選船先看載重，別只挑船頭雕得漂亮的。」"},"ja":{"name":"渡し場","originalName":"渡口","grade":"平","poem":["渡し場には二艘の舟","南へ北へそれぞれ向かう","どちらの舟がよいか問うなら","まず荷の重さを量れ"],"meaning":"二つの道に絶対的な優劣はありません。それぞれに必要な時間、資源、リスクが異なります。自分が何を背負えるかを確かめてから、どの代償を引き受ける価値があるか判断しましょう。","action":"二つの選択肢について、それぞれ必要になるコストを書き出しましょう。","quote":"「舟を選ぶなら積載量を見なさい。船首の彫刻が美しいというだけで決めてはならぬ。」","category":"選択"},"en":{"name":"The Ferry Crossing","originalName":"渡口","grade":"Neutral","poem":["Two boats wait at the ferry crossing;","One sails north, the other south.","If you ask which boat is better,","First weigh what you are carrying."],"meaning":"Neither path is absolutely better. Each asks for different amounts of time, resources, and risk. First understand what you can carry, then decide which cost is worth accepting.","action":"Write down the costs required by each of your two options.","quote":"“Check a boat’s capacity before choosing it. Do not pick one merely because its figurehead is pretty.”","category":"Decisions"}},{"id":83,"zh-Hant":{"id":83,"name":"兩門","grade":"待時","category":"抉擇","poem":["眼前開兩扇","門外路交橫","且繞牆邊看","或逢第三程"],"meaning":"眼前的選擇未必真的只能二選一。若兩個選項都不合適，可以重新界定問題，試著找出不同的做法。","action":"為目前的難題寫出第三個方案，即使它只是暫時安排。","quote":"「兩扇門都不好走，也可以先問問有沒有側門。」"},"ja":{"name":"二つの門","originalName":"兩門","grade":"時を待つ","poem":["目の前に二つの門が開き","門の外では道が交差する","塀のそばを回ってみれば","第三の道に出会うかもしれない"],"meaning":"目の前の選択は、本当に二者択一とは限りません。どちらも合わないなら、問題の定義そのものを見直し、別の方法を探してみましょう。","action":"今の難題について、たとえ暫定案でもよいので第三の選択肢を書いてみましょう。","quote":"「二つの門がどちらも通りにくいなら、脇門がないか尋ねてもよい。」","category":"選択"},"en":{"name":"Two Doors","originalName":"兩門","grade":"Wait for the Right Time","poem":["Two doors open before you;","Beyond them, the roads cross.","Walk around the wall and look again;","A third way may appear."],"meaning":"The choice before you may not truly be either-or. If neither option fits, redefine the problem itself and look for another way.","action":"Write down a third option for the problem, even if it is only a temporary arrangement.","quote":"“If neither door is easy to pass through, you may ask whether there is a side gate.”","category":"Decisions"}},{"id":84,"zh-Hant":{"id":84,"name":"觀星","grade":"中吉","category":"抉擇","poem":["星多難辨向","借問渡頭人","他言當參照","行路還由身"],"meaning":"參考別人的觀察，有助於發現自己沒看見的條件；但別人的經驗無法替代你的處境。聽完意見後，仍要由自己衡量。","action":"向一位值得信任、看法不同的人請教，整理可用而非照單全收的部分。","quote":"「看星星可以找方向，但腳穿哪雙鞋，還是你自己知道。」"},"ja":{"name":"星を眺める","originalName":"觀星","grade":"中吉","poem":["星が多すぎて方角を見失い","渡し場の人に道を尋ねる","他人の言葉は参考にしても","歩く足は自分のもの"],"meaning":"他人の観察を参考にすれば、自分が見落とした条件に気づけることがあります。しかし、他人の経験があなたの状況にそのまま当てはまるとは限りません。意見を聞いた後も、判断は自分で行いましょう。","action":"信頼できる人のうち、自分とは異なる見方をする人に相談し、使える部分だけを整理しましょう。","quote":"「星を見れば方角は分かる。だが、どの靴を履くかは自分が一番よく知っている。」","category":"選択"},"en":{"name":"Reading the Stars","originalName":"觀星","grade":"Moderately Favorable","poem":["Too many stars make the direction hard to see;","Ask someone at the ferry for guidance.","Let another person’s words serve as reference;","The feet that walk are still your own."],"meaning":"Other people’s observations can reveal conditions you may have missed. But their experiences cannot replace your own circumstances. Listen to advice, then weigh it for yourself.","action":"Ask someone you trust who sees things differently, then sort out which parts of their advice are useful to you.","quote":"“The stars can show you a direction. You are still the one who knows which shoes fit your feet.”","category":"Decisions"}},{"id":85,"zh-Hant":{"id":85,"name":"審印","grade":"吉","category":"抉擇","poem":["金印壓文書","條文細若絲","許諾須看透","方知所負時"],"meaning":"簽名、答應或加入一項安排之前，重要的是明白自己承擔了什麼。把權利義務講清楚，可以避免日後把誤解當成背叛。","action":"檢查一項即將作出的承諾，確認期限、責任與退出方式。","quote":"「印章蓋下去很快，後面要解釋可能得喝三壺茶。」"},"ja":{"name":"印を確かめる","originalName":"審印","grade":"吉","poem":["金の印が書状を押さえ","条文は糸のように細かい","約束をするなら隅々まで読み","何を負うか知っておこう"],"meaning":"署名する、承諾する、何かに参加する前に、自分が何を引き受けるのか理解することが大切です。権利と義務を明確にすれば、後から誤解を裏切りと取り違えずに済みます。","action":"これから行う約束を一つ確認し、期限、責任、退出する方法を確かめましょう。","quote":"「印を押すのは一瞬だが、その後の説明には茶を三壺飲むことになるかもしれぬ。」","category":"選択"},"en":{"name":"Examining the Seal","originalName":"審印","grade":"Favorable","poem":["A golden seal rests upon the document;","Its clauses are fine as threads.","Before making a promise, read it through;","Know what you will be carrying."],"meaning":"Before signing, agreeing, or joining an arrangement, understand what you are taking on. Clarifying rights and responsibilities can prevent misunderstandings from later being mistaken for betrayal.","action":"Review one commitment you are about to make and confirm its timeline, responsibilities, and exit terms.","quote":"“The seal takes a moment to stamp. Explaining it afterward may take three pots of tea.”","category":"Decisions"}},{"id":86,"zh-Hant":{"id":86,"name":"落子","grade":"上吉","category":"抉擇","poem":["棋局思千遍","燈芯已半燃","時機今可用","落子見新篇"],"meaning":"條件若已足以支持行動，無止境推演可能只是另一種延遲。你不需要保證結果完美，只需要對可預見的風險做好準備。","action":"選一件已想清楚的小事，今天做出第一個可驗證的行動。","quote":"「棋盤看久了不會自己下棋。該落子就落，別拿茶杯當棋子。」"},"ja":{"name":"一手を打つ","originalName":"落子","grade":"上吉","poem":["棋局を幾千度も思案し","灯芯はすでに半ば燃えた","今こそ時機を使うとき","一手を打てば新しい頁が開く"],"meaning":"行動を支える条件が十分にそろっているなら、際限のない検討は先延ばしの別名かもしれません。結果を完璧に保証する必要はありません。予測できるリスクに備えればよいのです。","action":"すでに考えがまとまっている小さなことを一つ選び、今日、検証できる行動に移しましょう。","quote":"「棋盤を眺め続けても、駒は自分で動かぬ。打つべき手を打ちなさい。茶碗を駒にしてはならぬ。」","category":"選択"},"en":{"name":"Making a Move","originalName":"落子","grade":"Very Favorable","poem":["The board has been studied a thousand times;","The lampwick is already half burned.","Now is the moment to use the opening;","One move can begin a new page."],"meaning":"If the conditions are sufficient to support action, endless analysis may simply be another form of delay. You do not need to guarantee a perfect result; prepare for the risks you can foresee.","action":"Choose one small matter you have already thought through and take a verifiable action today.","quote":"“The pieces will not move by themselves while you stare at the board. Make your move—and do not use the teacup as a chess piece.”","category":"Decisions"}},{"id":87,"zh-Hant":{"id":87,"name":"未題","grade":"平","category":"抉擇","poem":["案前留白紙","未寫亦安然","緩筆非逃避","心明再落箋"],"meaning":"暫時沒有答案，也可以是經過判斷的選擇。關鍵在於知道自己還需要什麼，而不是把拖延包裝成等待天意。","action":"替尚未決定的事情設定下一次檢視的日期與條件。","quote":"「白紙留著可以，記得別連墨都放到乾了。」"},"ja":{"name":"無題","originalName":"未題","grade":"平","poem":["机の前に白い紙を残し","まだ書かなくても穏やかでよい","筆を遅らせるのは逃げではない","心が澄んだら言葉を置こう"],"meaning":"今すぐ答えを出さないことも、判断を経た選択になり得ます。大切なのは、何がまだ必要なのかを分かっていることです。先延ばしを天意待ちと呼び替えないようにしましょう。","action":"まだ決めていないことについて、次に見直す日と、そのとき確認する条件を決めましょう。","quote":"「白紙を残しておくのはよい。墨まで乾かしてしまわぬように。」","category":"選択"},"en":{"name":"Untitled","originalName":"未題","grade":"Neutral","poem":["Leave a blank sheet upon the desk;","It is all right if nothing is written yet.","A slower hand is not always avoidance;","When the mind is clear, set down the words."],"meaning":"Choosing not to answer yet can itself be a considered decision. What matters is knowing what you still need. Do not disguise indefinite postponement as waiting for fate.","action":"Set a date to revisit the undecided matter and define what conditions you will review then.","quote":"“It is fine to leave the page blank. Just do not let the ink dry up while you wait.”","category":"Decisions"}},{"id":88,"zh-Hant":{"id":88,"name":"春信","grade":"吉","category":"運勢轉折","poem":["牆角新梅綻","寒枝已報春","一花非滿苑","卻可試行人"],"meaning":"眼前可能出現一些值得注意的好轉跡象。它還不能證明整個局面都已改變，但足以讓你試探性地往前走一步。","action":"觀察最近一個具體的正向變化，試著做一項低風險嘗試。","quote":"「看到一朵花，不必宣布全山春暖；但出門看看也無妨。」"},"ja":{"name":"春の便り","originalName":"春信","grade":"吉","poem":["塀の隅に梅が咲き","寒い枝が春を告げる","一輪で庭じゅうが満ちるわけではない","それでも歩き出してよい"],"meaning":"今、注目に値する好転の兆しが現れているかもしれません。それだけで状況全体が変わったとは言えませんが、低いリスクで一歩試してみるには十分です。","action":"最近起きた具体的な良い変化を一つ観察し、リスクの低い試みをしてみましょう。","quote":"「花が一輪咲いたからといって山じゅうが春とは言わぬ。だが、外を見に行くのはよい。」","category":"転機"},"en":{"name":"News of Spring","originalName":"春信","grade":"Favorable","poem":["A plum blossoms in the corner by the wall;","A winter branch announces spring.","One flower does not fill the whole garden;","Still, it is enough to begin walking."],"meaning":"A small sign of improvement may be appearing. It does not prove that the whole situation has changed, but it may be enough to justify one low-risk step forward.","action":"Notice one concrete positive change that has occurred recently and try one low-risk action.","quote":"“One flower does not mean the whole mountain has turned to spring. Still, there is no harm in going outside to look.”","category":"Turning Points"}},{"id":89,"zh-Hant":{"id":89,"name":"河清","grade":"上吉","category":"運勢轉折","poem":["濁浪逐風遠","清流照石紋","前程漸可辨","步穩不須奔"],"meaning":"先前的阻礙有逐步減少的可能，情況也更容易判斷。趁著視野清楚，把能完成的事穩穩做好，不必急於一次衝到底。","action":"把現在較明朗的一項機會拆成可執行的兩個步驟。","quote":"「水清了看得見石頭，不代表要閉著眼睛直接跳。」"},"ja":{"name":"澄む川","originalName":"河清","grade":"上吉","poem":["濁った波は風とともに遠ざかり","清流は石の模様を映す","前途は少しずつ見分けられ","歩みを安定させれば急ぐ必要はない"],"meaning":"以前の障害が少しずつ減り、状況を判断しやすくなる可能性があります。視界が澄んでいるうちに、できることを着実に進めましょう。一度に最後まで駆け抜ける必要はありません。","action":"今、見通しがよくなった機会を一つ選び、実行可能な二つの手順に分けましょう。","quote":"「水が澄んで石が見えるようになったからといって、目を閉じて飛び込む必要はない。」","category":"転機"},"en":{"name":"Clear Waters","originalName":"河清","grade":"Very Favorable","poem":["The muddy waves drift away with the wind;","Clear water reveals the patterns of stone.","The road ahead becomes easier to see;","Walk steadily—there is no need to run."],"meaning":"Obstacles that once stood in your way may gradually lessen, making the situation easier to assess. While the view is clear, steadily complete what you can. There is no need to rush all the way to the end.","action":"Choose one opportunity that has become clearer and break it into two actionable steps.","quote":"“Clear water lets you see the stones. That does not mean you should jump in with your eyes closed.”","category":"Turning Points"}},{"id":90,"zh-Hant":{"id":90,"name":"雷聲","grade":"平","category":"運勢轉折","poem":["遠雷驚野雀","雨勢尚難明","先收窗前物","再看雲幾層"],"meaning":"突如其來的消息可能讓人緊張，但聲勢不等於已經造成的影響。先確認事實、保護現有資源，再決定是否需要大幅調整。","action":"挑一項最近讓你焦慮的消息，查證來源與實際影響。","quote":"「聽到打雷先收衣服，不用立刻把房子拆了。」"},"ja":{"name":"雷鳴","originalName":"雷聲","grade":"平","poem":["遠雷に野の雀が驚き","雨の勢いはまだ分からない","まず窓辺の物をしまい","雲の重なりを見定めよ"],"meaning":"突然の知らせに緊張することはありますが、大きな音が実際の被害の大きさを示すとは限りません。まず事実を確認し、今ある資源を守ってから、大きく変える必要があるか判断しましょう。","action":"最近不安を感じた知らせを一つ選び、情報源と実際の影響を確かめましょう。","quote":"「雷が鳴ったら洗濯物を取り込めばよい。すぐに家を壊す必要はない。」","category":"転機"},"en":{"name":"Thunder","originalName":"雷聲","grade":"Neutral","poem":["Distant thunder startles the sparrows;","The rain’s force is not yet clear.","First bring in what rests by the window;","Then watch how the clouds gather."],"meaning":"Sudden news can be alarming, but the loudness of the announcement does not tell you how much impact it will actually have. Verify the facts and protect what you have before deciding whether major changes are needed.","action":"Choose one recent piece of news that has made you anxious and verify its source and actual impact.","quote":"“When thunder sounds, bring in the laundry. There is no need to demolish the house.”","category":"Turning Points"}},{"id":91,"zh-Hant":{"id":91,"name":"夜渡","grade":"待時","category":"運勢轉折","poem":["夜水深無岸","孤舟待月升","掌燈先辨路","莫任急潮乘"],"meaning":"局勢尚不明朗時，焦躁容易促使人選擇高風險的捷徑。當下適合蒐集線索、保留退路，而不是把希望全押在猜測上。","action":"列出目前最不確定的條件，先確認其中一項。","quote":"「看不見岸就先別比誰划得快，快掉水裡可不算效率。」"},"ja":{"name":"夜の渡し","originalName":"夜渡","grade":"時を待つ","poem":["夜の水は深く岸も見えず","小舟は月が昇るのを待つ","灯を掲げて先に道を見分け","急な潮に身を任せるな"],"meaning":"状況がまだ不明なとき、不安に駆られるとリスクの高い近道を選びがちです。今は手がかりを集め、退路を残すのに適した時です。推測だけに望みを賭けないでください。","action":"今もっとも不確かな条件をいくつか挙げ、そのうち一つを先に確認しましょう。","quote":"「岸が見えないなら、誰が速く漕ぐか競うのはやめなさい。水に落ちるのは効率とは言わぬ。」","category":"転機"},"en":{"name":"Crossing at Night","originalName":"夜渡","grade":"Wait for the Right Time","poem":["The night water is deep; no shore is in sight.","A lone boat waits for the moon to rise.","Lift a lamp and find the way first;","Do not surrender to the rushing tide."],"meaning":"When circumstances remain unclear, anxiety can push you toward a risky shortcut. This is a time to gather clues and preserve a way back, not to stake everything on a guess.","action":"List the conditions that remain most uncertain and verify one of them first.","quote":"“If you cannot see the shore, stop competing over who can row faster. Falling into the water is not efficiency.”","category":"Turning Points"}},{"id":92,"zh-Hant":{"id":92,"name":"秋實","grade":"中吉","category":"運勢轉折","poem":["稻穗垂金色","晨風過野田","春耕今有報","且把舊年編"],"meaning":"一段時間的努力可能已累積出成果，現在適合盤點、收尾與調整方向。收穫不必只看外界掌聲，也可以看自己真正學會什麼。","action":"整理一個完成的階段，記下成果與下一步想改進的地方。","quote":"「收成時記得算糧，不必每粒米都拍照給鄰居看。」"},"ja":{"name":"秋の実り","originalName":"秋實","grade":"中吉","poem":["稲穂は黄金色に垂れ","朝風が野を渡る","春の耕しは今、実を結ぶ","過ぎた年を編み直そう"],"meaning":"一定期間の努力が成果として積み上がり、今は振り返り、仕上げ、方向を調整するのに適しています。実りは外からの称賛だけで測る必要はありません。自分が何を身につけたかも見てください。","action":"一つの段階を整理し、成果と次に改善したい点を書き留めましょう。","quote":"「収穫のときは穀物を数えなさい。米粒の一つ一つを隣人に撮影して見せる必要はない。」","category":"転機"},"en":{"name":"Autumn’s Harvest","originalName":"秋實","grade":"Moderately Favorable","poem":["Golden rice heads bend low;","The morning wind crosses the fields.","The work of spring now bears its fruit;","Gather the past year into a new pattern."],"meaning":"Effort over time may have accumulated into results. This is a good moment to review, complete, and adjust your direction. Harvest is not measured only by outside applause; consider what you have truly learned.","action":"Review one completed stage and record both its results and what you would like to improve next.","quote":"“Count the grain at harvest. You do not need to photograph every single rice kernel for the neighbors.”","category":"Turning Points"}},{"id":93,"zh-Hant":{"id":93,"name":"有無","grade":"平","category":"隨緣／綜合","poem":["滿案皆珍物","心中尚覺空","若論得失處","須辨所求同"],"meaning":"擁有很多與感到滿足不是同一件事，放下也不必被視為輸。試著分辨自己追求的是物品、認同、關係，還是某種安全感。","action":"從最近一件得失中，寫下它對自己真正重要的原因。","quote":"「滿桌好菜還覺得餓，得先想想是不是吃錯餐。」"},"ja":{"name":"有るもの、無いもの","originalName":"有無","grade":"平","poem":["卓いっぱいに宝物が並んでも","心の中には空きが残る","得ることと失うことを語るなら","自分が何を求めるか見分けよ"],"meaning":"多くを所有することと、満たされていると感じることは同じではありません。手放すことも負けとは限りません。自分が求めているのは物、承認、関係、それとも安心感なのかを見分けましょう。","action":"最近の得失を一つ取り上げ、それが自分にとって本当に重要だった理由を書きましょう。","quote":"「ごちそうが並んでいるのにまだ空腹なら、まず食べているものが合っているか考えなさい。」","category":"人生・総合"},"en":{"name":"Having and Wanting","originalName":"有無","grade":"Neutral","poem":["The table is filled with precious things;","Still, an emptiness remains within.","When speaking of gain and loss,","First discern what you truly seek."],"meaning":"Having many things is not the same as feeling fulfilled, and letting go does not have to mean losing. Consider whether what you seek is an object, recognition, a relationship, or a sense of security.","action":"Choose one recent gain or loss and write down why it truly mattered to you.","quote":"“If you are still hungry with a feast before you, first consider whether you are eating the right thing.”","category":"General Guidance"}},{"id":94,"zh-Hant":{"id":94,"name":"莫問","grade":"吉","category":"隨緣／綜合","poem":["問盡山中鳥","無從定雨晴","與其求萬兆","不若踏前程"],"meaning":"不必替每一件偶然尋找特別的預兆。當資訊足夠、責任可承擔時，實際行動往往比反覆詢問更能帶來答案。","action":"暫停反覆確認同一個問題，先完成一項能直接改善現況的事。","quote":"「貧道歡迎你來問事，但也不想變成你家冰箱的開門顧問。」"},"ja":{"name":"問うなかれ","originalName":"莫問","grade":"吉","poem":["山の鳥すべてに尋ねても","雨が晴れるかは定まらない","幾千の兆しを求めるより","自ら道へ踏み出そう"],"meaning":"すべての偶然に特別な前兆を探す必要はありません。情報が十分で、責任を引き受けられるなら、何度も問い直すより実際に動くことが答えにつながります。","action":"同じ問いを何度も確認するのをいったん止め、状況を直接よくする行動を一つ完了しましょう。","quote":"「問事に来るのは歓迎する。だが、冷蔵庫の扉を開ける係にまでなりたくはない。」","category":"人生・総合"},"en":{"name":"Ask No More","originalName":"莫問","grade":"Favorable","poem":["Ask every bird upon the mountain;","None can settle whether the rain will clear.","Rather than seeking a thousand omens,","Step onto the road yourself."],"meaning":"You do not need to search for a special omen in every coincidence. When you have enough information and can accept the responsibility, taking action often brings more answers than asking the same question again and again.","action":"Pause the repeated checking of one question and complete one action that directly improves the situation.","quote":"“You are welcome to come and ask for guidance. I simply do not wish to become the person responsible for opening your refrigerator.”","category":"General Guidance"}},{"id":95,"zh-Hant":{"id":95,"name":"石階","grade":"中吉","category":"隨緣／綜合","poem":["階前青草細","一步有苔痕","不問千山遠","先行此一門"],"meaning":"方向不明時，不一定得先決定一生的路。先做好當下最能確定的一步，讓下一個問題在行動裡慢慢出現。","action":"選出今日最小且重要的一件事，不再等完整計畫才開始。","quote":"「樓梯一階一階走，比站在一樓研究屋頂快。」"},"ja":{"name":"石段","originalName":"石階","grade":"中吉","poem":["階の前には細い草が生え","一歩ごとに苔の跡が残る","遠い山々を問うことなく","まずこの門を一歩進もう"],"meaning":"方向が分からないとき、人生の道をすべて先に決める必要はありません。今、最も確かな一歩を踏み出せば、次の問いは行動の中で少しずつ見えてきます。","action":"今日できる、最も小さくても大切なことを一つ選び、完全な計画を待たずに始めましょう。","quote":"「階段は一段ずつ上るほうが、一階に立って屋根の研究をするより早い。」","category":"人生・総合"},"en":{"name":"Stone Steps","originalName":"石階","grade":"Moderately Favorable","poem":["Fine grass grows beside the steps;","Each footfall leaves a trace in the moss.","Do not ask how far the distant mountains lie;","First take one step through this gate."],"meaning":"When the direction is unclear, you do not have to decide the entire course of your life in advance. Take the surest step available now, and the next question may emerge through action.","action":"Choose one small but important thing you can do today, and begin without waiting for a complete plan.","quote":"“Climbing the stairs one step at a time is faster than standing on the ground floor studying the roof.”","category":"General Guidance"}},{"id":96,"zh-Hant":{"id":96,"name":"換席","grade":"平","category":"隨緣／綜合","poem":["昨日居前座","今朝換後庭","席遷人未改","何必棄曾經"],"meaning":"身分與環境會改變，但過去的經驗不必因此被否定。重新安排自己的位置，可以保留有用的部分，也可以不再接受原本的束縛。","action":"寫下現在希望保留的一項舊經驗，以及想放下的一項舊要求。","quote":"「換張椅子坐，不代表以前那張就得當柴燒。」"},"ja":{"name":"席を替える","originalName":"換席","grade":"平","poem":["昨日は前の席に座り","今日は奥の席へ移る","席が変わっても人は変わらない","過ぎた日々を捨てることはない"],"meaning":"立場や環境が変わっても、過去の経験まで否定する必要はありません。自分の位置を新しく整えながら、役立つものは残し、以前の束縛は受け入れない選択ができます。","action":"今の自分が残したい過去の経験を一つ、手放したい古い要求を一つ書きましょう。","quote":"「椅子を替えたからといって、前の椅子を薪にする必要はない。」","category":"人生・総合"},"en":{"name":"A Change of Seat","originalName":"換席","grade":"Neutral","poem":["Yesterday you sat in the front row;","Today you move to a seat farther back.","Your place has changed, but you remain yourself;","There is no need to discard what came before."],"meaning":"Changes in status or environment do not require you to reject your past experience. You can rearrange your place, keep what remains useful, and stop accepting constraints that no longer fit.","action":"Write down one past experience you want to keep and one old expectation you want to release.","quote":"“Changing seats does not mean you have to turn the old chair into firewood.”","category":"General Guidance"}},{"id":97,"zh-Hant":{"id":97,"name":"不染","grade":"上吉","category":"隨緣／綜合","poem":["清泉行石上","濁影過無痕","任爾千聲議","心中自有門"],"meaning":"別人的評價可以參考，卻不必成為你做所有決定的唯一準繩。持守原則也不表示拒絕修正，真正的穩定容得下反證。","action":"用自己的話重述一項核心價值，並想想什麼證據會讓你調整看法。","quote":"「不隨風倒很好，但若地基歪了，還是要肯修。」"},"ja":{"name":"染まらず","originalName":"不染","grade":"上吉","poem":["清らかな泉は石の上を流れ","濁った影は跡を残さず過ぎる","幾千の声に論じられても","心には自分の門がある"],"meaning":"他人の評価は参考にできますが、すべての決断を左右する唯一の基準にする必要はありません。原則を守ることは、修正を拒むことではありません。本当に安定した考えは、反証を受け入れる余地も持っています。","action":"自分の大切な価値観を自分の言葉で言い直し、どんな証拠があれば考えを修正するかも考えましょう。","quote":"「風に流されないのはよい。だが、土台が傾いているなら直すことも必要だ。」","category":"人生・総合"},"en":{"name":"Unstained","originalName":"不染","grade":"Very Favorable","poem":["A clear spring runs over stone;","A murky shadow passes without a trace.","Let a thousand voices debate around you;","Your heart still has a gate of its own."],"meaning":"Other people’s opinions can be useful, but they need not become the sole measure of every decision. Holding to your principles does not mean refusing correction. A truly stable view can make room for evidence that challenges it.","action":"Restate one core value in your own words, then consider what evidence might lead you to revise your view.","quote":"“It is good not to be blown about by every wind. But if the foundation is crooked, you must still repair it.”","category":"General Guidance"}},{"id":98,"zh-Hant":{"id":98,"name":"再會","grade":"待時","category":"隨緣／綜合","poem":["舊路逢秋葉","橋頭人未還","重逢隨有緣","不必守空山"],"meaning":"重逢可以期待，卻不能成為停止自己生活的理由。是否再聯繫，應看彼此現在的意願與情況，而不是把過去當作永恆契約。","action":"想想若對方一直沒有回來，你還想如何安排接下來的生活。","quote":"「橋頭等人可以，別把自己等成觀光景點。」"},"ja":{"name":"再会","originalName":"再會","grade":"時を待つ","poem":["古い道に秋の葉が落ち","橋のたもとに人はまだ戻らない","再会は縁に任せればよい","空しい山を守り続けるな"],"meaning":"再会を願うことはできますが、それを理由に自分の生活を止めてはいけません。再び連絡を取るかどうかは、過去を永遠の契約と見なすのではなく、今の双方の意思と状況で決めましょう。","action":"相手が戻ってこなかったとしても、自分はこれからの暮らしをどうしたいか考えてみましょう。","quote":"「橋のたもとで人を待つのはよい。自分まで観光名所になってはならぬ。」","category":"人生・総合"},"en":{"name":"Meeting Again","originalName":"再會","grade":"Wait for the Right Time","poem":["Autumn leaves fall upon the old road;","The person has not returned to the bridge.","Let reunion depend on the ties that remain;","Do not keep watch over an empty mountain."],"meaning":"You may hope to meet again, but that hope should not put your own life on hold. Whether to reconnect should depend on both people’s present wishes and circumstances, not on treating the past as an eternal contract.","action":"Consider how you would like to arrange your life if the other person never returns.","quote":"“It is all right to wait for someone by the bridge. Just do not turn yourself into a tourist attraction.”","category":"General Guidance"}},{"id":99,"zh-Hant":{"id":99,"name":"知止","grade":"上吉","category":"隨緣／綜合","poem":["行遠知歸處","臨淵識止時","心明無定數","一步自成詩"],"meaning":"知止不是凡事退讓，而是知道什麼值得堅持、什麼應當停手。你不必等所有答案都由外界宣布，能清楚選擇並承擔，便已走在自己的路上。","action":"確定眼前最重要的一件事：該停止什麼，又願意為什麼開始行動。","quote":"「貧道替你解籤，不替你走路。要真能算盡每一步，我今日也不必自己掃院子了。」"},"ja":{"name":"知止（ちし）","originalName":"知止","grade":"上吉","poem":["遠くまで歩けば帰る場所を知り","淵に臨めば止まる時を知る","心が明らかでも定まった数はなく","一歩ごとに自分の詩が生まれる"],"meaning":"知止とは、何事にも譲ることではありません。何を守る価値があり、何をやめるべきかを知ることです。すべての答えを外から告げられるまで待つ必要はありません。自分で明確に選び、その責任を引き受けるなら、すでに自分の道を歩いています。","action":"今もっとも大切なことを一つ定めましょう。何をやめ、何のために行動を始めるのかを決めてください。","quote":"「貧道は籤を解くが、あなたの代わりに歩くことはできぬ。すべての一歩を占えるなら、今日も庭を掃いてはおらぬ。」","category":"人生・総合"},"en":{"name":"Knowing When to Stop","originalName":"知止","grade":"Very Favorable","poem":["Travel far, and learn where you may return;","Stand at the deep edge, and know when to stop.","A clear heart follows no fixed number;","Each step becomes a verse of its own."],"meaning":"Knowing when to stop does not mean yielding in every matter. It means recognizing what is worth standing for and what should be left behind. You do not have to wait for the outside world to announce every answer. When you choose clearly and accept responsibility, you are already walking your own path.","action":"Identify what matters most right now. Decide what you need to stop doing and what you are willing to begin doing—and why.","quote":"“I can interpret a lot for you, but I cannot walk your road. If I could foretell every step, I would not be sweeping the courtyard today.”","category":"General Guidance"}}],"translationNotes":{"ja":"詩句は原文の情景と含意を優先した意訳。四句構成を維持し、現代の日本語として自然に読める表現に調整。","en":"The poems are literary translations that preserve the imagery and intent rather than forcing word-for-word equivalence. Each remains a four-line poem.","daoistTitle":{"zh-Hant":"知止道長","ja":"知止道長","en":"Daoist Priest Zhizhi"}}};
