// Storage can be unavailable when this page is opened directly via file://.
// Keep language switching fully functional even when preference persistence is blocked.
function readSavedLanguage(){
  try { return localStorage.getItem('qinghe-language'); }
  catch (_) { return null; }
}
function saveLanguagePreference(value){
  try { localStorage.setItem('qinghe-language', value); }
  catch (_) { /* Local preview still works; preference simply will not persist. */ }
}
