function selectedTopic(){return document.querySelector('input[name="topic"]:checked').value;}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('on'),2600);}
function lotNumber(n){return language==='zh-Hant'?`第${numChinese(n)}籤`:language==='ja'?`第${n}番`: `Lot ${n}`;}
