  set('hero-title-top',u.titleTop);set('hero-title-bottom',u.titleBottom);set('intro-line-1',u.intro1);set('intro-line-2',u.intro2);
  set('lot-count-label',u.lotCount);const countNote=$('lot-count-label').parentElement;countNote.lastChild.textContent=language==='zh-Hant'?' 99 支心籤':language==='ja'?' 99の心籤':' 99 Heart Lots';set('topic-title',u.topicTitle);set('topic-desc-1',u.topicDesc1);set('topic-desc-2',u.topicDesc2);
  set('question-label-text',u.questionLabel);set('question-optional',u.questionOptional);$('question').placeholder=u.placeholder;set('privacy-line',u.privacy);
  set('draw-section-label',u.drawSection);set('draw-btn',u.draw);set('draw-hint',u.drawHint);set('lot-caption',u.lotCaption);
