function showLot(lot,topic){$('result-number').textContent=lotNumber(lot.id);$('result-name').textContent=lot.name;$('result-grade').textContent=lot.grade;$('result-poem').replaceChildren(...lot.poem.map(line=>{const s=document.createElement('span');s.textContent=line;return s;}));$('result-meaning').textContent=lot.meaning;$('result-action').textContent=lot.action;$('result-quote').textContent=lot.quote;$('result-topic').textContent=`${UI[language].topicLabel} / ${translatedTopic(topic)}`;resultSection.hidden=false;setTimeout(()=>resultSection.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}),70);}
function drawLot(){if(isDrawing)return;playDrawSound();isDrawing=true;drawBtn.disabled=true;drawBtn.textContent=UI[language].drawWait;hint.textContent=language==='zh-Hant'?'籤筒輕響，稍候片刻。':language==='ja'?'籤筒が静かに鳴っています。少々お待ちください。':'The lot筒 is gently rattling. One moment…';stage.classList.add('shaking');resultSection.hidden=true;
  // Avoid immediately repeating an identical slip in the same page session. No questions are stored.
  const excluded=current?.lot?.id;let index=randomIndex(LOTS.length);if(excluded!=null&&LOTS[index].id===excluded){index=(index+1+randomIndex(LOTS.length-1))%LOTS.length;}
  const lot=LOTS[index],topic=selectedTopic();
  setTimeout(()=>{current={lot,topic,question:$('question').value.trim()};stage.classList.remove('shaking');drawBtn.disabled=false;drawBtn.textContent=UI[language].drawAgain;hint.textContent=UI[language].drawDone;isDrawing=false;showLot(lot,topic);},1350);
}
drawBtn.addEventListener('click',drawLot);
$('again-btn').addEventListener('click',()=>{resultSection.hidden=true;$('question').value='';hint.textContent=language==='zh-Hant'?'換一個問題，再求一籤。':language==='ja'?'問いを変えて、もう一籤引いてください。':'Change your question and draw another lot.';$('ritual').scrollIntoView({behavior:'smooth',block:'start'});});
function normalizeCopyText(text){return String(text).replace(/\r\n?/g,'\n').replace(/\\+r\\+n/g,'\n').replace(/\\+n/g,'\n').replace(/\\+r/g,'\n');}
function textToCopy(includeQuestion=false){const {lot,topic,question}=current;const u=UI[language];const intro=language==='zh-Hant'?`清和觀｜知止籤\n第${numChinese(lot.id)}籤・${lot.name}（${lot.grade}）`:language==='ja'?`清和観｜知止籤\n${lotNumber(lot.id)}・${lot.name}（${lot.grade}）`:`Qinghe Guan | Zhizhi Heart Lots\n${lotNumber(lot.id)} · ${lot.name} (${lot.grade})`;
  if(includeQuestion){if(language==='zh-Hant')return `知止道長，我剛在《清和觀｜知止籤》求到「第${numChinese(lot.id)}籤・${lot.name}」。\n所問：${translatedTopic(topic)}${question?`\n我想問的是：${question}`:''}\n籤詩：\n${lot.poem.join('\n')}\n你會怎麼解這支籤？`;return language==='ja'?`知止道長、先ほど《清和観｜知止籤》で${lotNumber(lot.id)}「${lot.name}」を引きました。\nテーマ：${translatedTopic(topic)}${question?`\n質問：${question}`:''}\n籤詩：\n${lot.poem.join('\n')}\nこの籤をどう読み解きますか？`:`Daoist Priest Zhizhi, I drew ${lotNumber(lot.id)}, “${lot.name},” from Qinghe Guan’s Heart Lots.\nTopic: ${translatedTopic(topic)}${question?`\nMy question: ${question}`:''}\nPoem:\n${lot.poem.join('\n')}\nHow would you interpret this lot?`;}
  if(language==='zh-Hant')return `${intro}\n所問之事：${translatedTopic(topic)}\n\n${lot.poem.join('\n')}\n\n【籤解】${lot.meaning}\n【行動提醒】${lot.action}\n${lot.quote}\n\n原創虛構互動作品・非正式宗教科儀`;
  return language==='ja'?`${intro}\nテーマ：${translatedTopic(topic)}\n\n${lot.poem.join('\n')}\n\n【籤解】${lot.meaning}\n【行動のヒント】${lot.action}\n${lot.quote}\n\nオリジナルの架空インタラクティブ作品・正式な宗教儀式ではありません`:`${intro}\nTopic: ${translatedTopic(topic)}\n\n${lot.poem.join('\n')}\n\n[Interpretation] ${lot.meaning}\n[One Small Action] ${lot.action}\n${lot.quote}\n\nOriginal fictional interactive work · Not a religious ceremony`;
}
async function copyText(text){text=normalizeCopyText(text);try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return true;}const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;opacity:0;top:0;left:0;';document.body.append(area);area.select();const success=document.execCommand('copy');area.remove();return success;}catch{return false;}}
$('copy-btn').addEventListener('click',async()=>{if(!current)return;toast(await copyText(textToCopy())?UI[language].copied:UI[language].copyFail);});
$('ask-btn').addEventListener('click',async()=>{if(!current)return;toast(await copyText(textToCopy(true))?UI[language].askCopied:UI[language].copyFail);});
// Export a self-contained 1080 × 1350 PNG. User-entered questions are intentionally excluded.
function roundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();}
function wrapCjk(ctx,text,maxWidth){const lines=[];let line='';for(const c of text){const test=line+c;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=c;}else line=test;}if(line)lines.push(line);return lines;}
