  const labels=language==='zh-Hant'?{brand:'清  和  觀     ／     知  止  心  籤',english:'Q I N G H E   G U A N',lot:`第 ${numChinese(lot.id)} 籤`,meaning:'此 籤 怎 麼 說',footer:'一支籤，不替你決定人生。',disclaimer:'原創虛構世界觀互動籤詩・非正式宗教科儀'}:language==='ja'?{brand:'清 和 観 ／ 知 止 心 籤',english:'Q I N G H E   G U A N',lot:`第 ${lot.id} 番`,meaning:'この籤が伝えること',footer:'一籤は、あなたの人生を決めません。',disclaimer:'架空の物語世界をもとにした作品・正式な宗教儀式ではありません'}:{brand:'QINGHE GUAN  /  ZHIZHI HEART LOTS',english:'99 ORIGINAL LOTS',lot:`LOT ${lot.id}`,meaning:'WHAT THIS LOT SAYS',footer:'A lot does not decide your life.',disclaimer:'Original fictional interactive work · Not a religious ceremony'};
  const bg=x.createLinearGradient(0,0,w,h);bg.addColorStop(0,'#f7f0e4');bg.addColorStop(1,'#e7dcc7');x.fillStyle=bg;x.fillRect(0,0,w,h);
